import{_ as i,O as r,o as n,c as o,a as s,i as a,f as l}from"./chunks/framework.fmIt2z2h.js";const b=JSON.parse('{"title":"第二部分　边界与方法","description":"","frontmatter":{"title":"第二部分　边界与方法","xkChars":7944,"xkLessons":{"intro-02-part":{"title":"第二部分　边界与方法","lead":"能进入讨论、能得到哪一种支持、能否据此行动，是三道不同的问题。第二部分先给整部理论划定使用范围，再说明不同结论各自欠什么证据。","explanation":["原文定位：第205—212行；原文锚点 part_2；短引文：‘属于广义经验结构世界，只意味着原则上可以建立合同’。本题源切片逐字附后，讲解与原文分开。","这里的“广义”是对象种类广：自然过程、技术、生态、人类行动和制度都可以成为候选；“经验”则收紧了入口：必须有可比较的材料，并能把对象、状态、关系或转移、接口、时间、尺度与同一性说清。它不是宣称所有这些领域已经被一种机制统一解释，更不是证明世界必有统一目的。","“人类结构化世界”是其中一类对象。谈人时需要追加人的角色、文化、规范和授权，不能把人的目的搬给风、水、算法或生态过程；同样不能因对象是人，就认为事实判断天然带着处分权。第一部分的总纲在此被改写为工作中的边界，后文H、N、O分别承接领域适配、价值前提和操作程序。","每次应用必须重新写当前合同：对象是谁，SP表示哪一种尺度剖面，T是哪段时间，K凭什么说前后仍是同一对象；再列环境、地区、资料窗口、外推单元和排除项。广泛的总对象域不替代这个窄合同。例如给某一窗口的队列建模，并不等于已经解释所有队列，也不等于能在别的制度中直接照搬处理方法。","纯形而上命题可以作为哲学问题讨论，但若没有任何可比较材料和经验字段，它不能借用本书经验判断的证据等级。这条限制针对结论身份，并不宣判该问题毫无意义。另一方面，有经验字段也只足以提出可检验的问题，具体支持还在后续实例中建立。"],"distinctions":[{"leftTitle":"对象域","leftText":"哪些种类原则上允许被研究。","rightTitle":"本次适用范围","rightText":"本次实际研究的对象、时间、尺度、环境和排除项。"},{"leftTitle":"解释对象","leftText":"说明怎样形成、运作、转化或解体。","rightTitle":"替对象设目的","rightText":"声称它追求某种目标；这需要对象类型与材料支持。"}],"boundaries":["没有经验字段的“系统”不能获得经验结论等级；一个可观察对象也不会因为被命名就自动获得正式G支持。","缩小适用范围通常是在校正外推，不是撤销所有已经得到支持的局部事实。","自然过程的筛选、技术系统的输出和人的意图不能仅因都出现“选择”一词而等同。"],"questions":["一项结论来自某校一个学期，研究者说“学校都属于人类结构化世界，所以适用于所有学校”。缺了什么？","一个数学模型解释了资源分配结果，是否已经回答“怎样分配才正当”？"],"diagramPath":"/reading-assets/S-2-1/figures/intro-02-part.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-02-part","start_line":205,"end_line":212,"startLine":205,"endLine":212}],"outputId":"intro-02-part","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：经验判断需要可比较材料和明确指称，否则不同观察无法知道在比较什么。","连接：对象域广并不能排除环境、时间和测量差异，所以总范围必须逐次收缩为当前合同。","结论：可以在多种对象上开展结构解释，但每条结论只在有材料和桥接的范围内成立。","责任：描述和解释由材料与推理承担；“应保护谁、谁可行动”还要公开规范前提及授权，不能由对象的可研究性推出。"],"teachingExamples":[{"title":"教学构造：一条传送带的范围合同","text":"假设只研究某工厂白班的一段传送带：B是入口与出口，X为带速与排队件数，R为到达和离开规则，I为上下游接口，T为一个班次，SP是九轴剖面：本例简写A聚合层次为这一段设备、X空间范围为指定入口至出口、T时间跨度为一个班次、R观察分辨率为带速和队列的登记采样协议；K为设备及接口保持指定关系。未展开的O组织、C因果、I影响、N网络、J管辖授权五轴只是本教学例省略，完整应用仍须逐轴登记状态，确不适用须写理由，不能把SP缩成分辨率一轴。它说明“问哪一段过程”。若夜班换了产品或接口，旧合同不能自动覆盖。","assumptions":"所有设备和时段均为示意，不含任何实际观测数据。","boundary":"例子只展示字段用途，不证明该分组有解释增益，也不授权改变生产。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：给“所有不顺利的事”取名为某系统，却没有共同状态、窗口或可比较材料。","effect":"一个名称无法产生可检验的经验对象；可保留为叙事问题，不可赋予经验支持等级。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一项结论来自某校一个学期，研究者说“学校都属于人类结构化世界，所以适用于所有学校”。缺了什么？","answer":"缺的是跨对象、时期、环境的桥接与外推依据。属于同一总对象域只允许研究，并不保证同一机制或效应。","basis":"本节原文及上述公开推导"},{"question":"一个数学模型解释了资源分配结果，是否已经回答“怎样分配才正当”？","answer":"没有。模型可说明给定规则的结果；正当性需要明确价值前提、利益与风险、决定者及授权程序。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-1/figures/intro-02-part.png","alt":"广义经验对象域，有可比较材料；本次合同，对象／SP／T／K；有限结构解释，结论随条件成立；人类对象的追加问题，角色／意义／价值；规范与操作程序，保护理由／授权；可采用的行动范围，另有证据与权限。概念图，依据本导语；上下两路不得自动互推，非经验数据图。","caption":"概念图，依据本导语；上下两路不得自动互推，非经验数据图。"}],"diagramBrief":"静态双路径图：上路回答解释到哪里，下路回答谁可以做什么。可设“对象／时间窗变化”切换，只高亮需重核的合同，不显示虚构成功率。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本导语划定对象域与使用范围，教学合同直接说明其逻辑；附加史实不能验证这一范围选择，故不强配真实案例。"},"openQuestions":[],"taskId":"S-2-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第205—238行；每节精确范围见sourceRefs","claim_support":["intro-02-part：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-f1","title":"Xikari 条件形式命题与九轴定义","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18—§4.19：981—1028行；F1精确定义985—988行；§5.2九轴1039—1059行","claim_support":["2.1.2：目标恢复的同表示恒定条件及静态恢复不自动动力闭合。","导语教学例：SP为九轴尺度剖面，非单一观察分辨率。"],"limits":["模型内条件命题和定义不提供外部经验支持。"],"access_status":"read"},{"id":"snow-context","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版印刷页39—41、51—52；Gutenberg文本The Cholera near Golden Square和The Pump-well in Broad Street","claim_support":["2.1.1：Snow记述死亡登记与饮水调查、9月7日面谈及次日移除泵柄。","2.1.1：原作承认停用前发病下降，无法确定停用时井水仍有致病作用。"],"limits":["只读并使用相关原作段落；未复核登记簿与个体数据。","调查记述不是现代随机干预，也不是本框架结果前G合同。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-1/lecture.md","sourcesPath":"/reading-assets/S-2-1/sources.json","sourceSlicePath":"/reading-assets/S-2-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-1/diagrams.md"},"2.1":{"title":"2.1　两阶段对象准入","lead":"先把问题写清，再检验它。登记候选像写研究问题的地址；正式支持则要靠事前说定的比较与结果，不能把这两步倒过来。","explanation":["原文定位：第213—224行；原文锚点 section-2-1；短引文：‘字段完整只证明问题已经被说清楚’。本题源切片逐字附后，讲解与原文分开。","D0中的S*=〈B,X,R,I,T,SP,K〉依次列出边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面、同一性判据。星号提醒读者它是候选。写满字段不证明边界最优、对象相对独立或机制存在；缺了关键字段时可以探索，但不能假称合同已经清楚。","第二阶段只管理申请G1—G4正式实例支持的主张及依赖这种支持的C、CM强经验主张。G1问分组增益，G2问指定通道，G3问相对于当前表示的历史条件增量，G4问表示闭合与转换。G3尤其不是“历史是否曾经影响过现在”的泛问。研究者必须选择对应问题，而不能用某一类结果替另一类背书。","查看结果前要冻结不可变版本和可审计时间戳：N0、唯一子型、该子型允许的唯一成功判据、控制与模型、样本和外推单位、指标、正向阈值、决策与零结论规则、证伪和暂停条件。多目标、多模型还要冻结主目标或聚合、模型选择或集成、多重比较规则。冻结的目的不是让世界服从表格，而是防止看到结果后移动问题和成功线。","确认或复制实例依事前合同完成并过门，才有相应正向支持资格；反驳实例只支持原先登记的反驳或零判断。探索、草案、证据后偏离和未披露偏离不能沿“正式支持”边进入要求此资格的C分支。有偏离可诚实记录并重新提案，不能把探索历史擦掉。","至少保留四种状态：已登记候选；正向未获支持；零模型获得支持；对象得到有限正向支持。正向没过可能来自效应小、测量不足、样本不足或模型不适合，并非自动“没有”。要支持预定容差内的等价或充分性，还须事前给零结论规则、功效或灵敏度并通过相应标准。2.1.1保留旧研究本来有据的内容，2.1.2则防止把形式证明当作现实样本。"],"distinctions":[{"leftTitle":"D0完成","leftText":"对象问题可描述。","rightTitle":"G-instance支持","rightText":"某个事前冻结的经验问题得到有限支持。"},{"leftTitle":"正向未获支持","leftText":"没有通过正向规则，仍可能未决。","rightTitle":"零模型支持","rightText":"按预先规定的零规则排除了具有意义的偏离。"},{"leftTitle":"经验效应真假","leftText":"世界中是否存在所问的差异。","rightTitle":"正式支持资格","rightText":"当前资料和研究程序是否足以按该框架给出特定支持。"}],"boundaries":["本程序不作为所有领域知识、历史记录和日常理解的统一真值门；已有研究不能因没有G合同而一概作废。","阈值不是随手画线即可获得科学性。测量有效性、样本选择、竞争解释和外推条件仍要另证。","同一数据反复调整模型并不能变成独立确认；保留探索身份后，才可设计真正新的检验。"],"questions":["某组结果未达到正向阈值，但没有预登记等价容差。应填“零模型成立”吗？","登记完整D0后，能否直接写“这个系统已经有客观独立地位”？","同一资料已帮助选择模型，后来把文件锁定，是结果前冻结吗？"],"diagramPath":"/reading-assets/S-2-1/figures/section-2-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.1","start_line":213,"end_line":224,"startLine":213,"endLine":224}],"outputId":"section-2-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提一：分析者可以先选边界与表示，但选择本身不是该选择有经验地位的证据。","前提二：若比较方法、阈值或模型随已见结果改变，正向结果可能来自事后选择，无法按原合同解释。","连接：先用D0确定候选，再在证据前固定所申请G子型的检验合同，使“问什么”和“怎样判”可复核。","结论：资格赋予满足合同的具体实例，不赋予空白模板，也不赋予所有填写完整的候选。","零判断责任：未拒绝N0与支持预定意义的N0不等价；等价性／充分性、容差及识别灵敏度要各自满足。"],"teachingExamples":[{"title":"教学构造：登记一条排队线，不等于证明分组有用","text":"设研究者想知道把服务请求按接口分组，是否比不分组更准确预测等待时长。先登记B、X、R、I、T、SP、K；再在独立评价窗口前固定基线、误差指标、最小改进和评价规则。若见到评价结果后改分组，所得模式可以是新候选，却不能冒充此前已冻结的确认。这里没有实施研究，也没有虚构改进数字。","assumptions":"待比较问题是G1式分组增益，不是因果干预效果；需实际资料才能形成正式实例。","boundary":"例子是程序教学，不声称已通过G1，也不因候选完整推出服务质量改善。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学条件反例：只用两个噪声很大的测量，正向阈值未过，便宣布“效果为零”。","effect":"缺乏事前零规则与灵敏度，最多未获正向支持；小样本失败不能自动排除有意义差异。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学条件反例：研究者用同一评价结果挑出最好的十种分组之一，再把该分组写成“唯一预注册模型”。","effect":"破坏证据前冻结；诚实的身份是探索及偏离记录，而不是确认支持。","sourceIds":["theory"]}],"questionAnswers":[{"question":"某组结果未达到正向阈值，但没有预登记等价容差。应填“零模型成立”吗？","answer":"不应。可填正向未获支持或未决；零结论需要额外的规则与足够灵敏度。","basis":"本节原文及上述公开推导"},{"question":"登记完整D0后，能否直接写“这个系统已经有客观独立地位”？","answer":"不能。D0只固定候选所指；相对独立性、分组增益或其他经验主张须有对应比较和证据。","basis":"本节原文及上述公开推导"},{"question":"同一资料已帮助选择模型，后来把文件锁定，是结果前冻结吗？","answer":"对已用来选模型的资料不是。应说明资料暴露和探索用途，使用新的合适确认材料时再冻结新合同。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-1/figures/section-2-1.png","alt":"D0字段明确，仍是候选 S*；证据前冻结G合同，唯一子型与规则；确认／复制按合同执行，再评价结果；探索或事后偏离，保留候选／偏离；正向规则未通过，未支持或未决；通过相应规则，有限正向支持。概念图，依据2.1；未通过正向门不自动通向N0支持，零判断另核事前规则和灵敏度。","caption":"概念图，依据2.1；未通过正向门不自动通向N0支持，零判断另核事前规则和灵敏度。"}],"diagramBrief":"静态状态图。交互可切换“确认／探索”和“正向／零规则”，显示资格分支；不得把未决自动着色为零效应。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是正式支持的程序条件，构造能明确显示状态差异；真实历史材料放入下节检验“旧证据身份”边界，本节不伪造实际预注册实例。"},"openQuestions":[],"taskId":"S-2-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第205—238行；每节精确范围见sourceRefs","claim_support":["intro-02-part：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-f1","title":"Xikari 条件形式命题与九轴定义","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18—§4.19：981—1028行；F1精确定义985—988行；§5.2九轴1039—1059行","claim_support":["2.1.2：目标恢复的同表示恒定条件及静态恢复不自动动力闭合。","导语教学例：SP为九轴尺度剖面，非单一观察分辨率。"],"limits":["模型内条件命题和定义不提供外部经验支持。"],"access_status":"read"},{"id":"snow-context","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版印刷页39—41、51—52；Gutenberg文本The Cholera near Golden Square和The Pump-well in Broad Street","claim_support":["2.1.1：Snow记述死亡登记与饮水调查、9月7日面谈及次日移除泵柄。","2.1.1：原作承认停用前发病下降，无法确定停用时井水仍有致病作用。"],"limits":["只读并使用相关原作段落；未复核登记簿与个体数据。","调查记述不是现代随机干预，也不是本框架结果前G合同。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-1/lecture.md","sourcesPath":"/reading-assets/S-2-1/sources.json","sourceSlicePath":"/reading-assets/S-2-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-1/diagrams.md"},"2.1.1":{"title":"2.1.1 领域证据与正式实例资格","lead":"旧研究可以有价值，同时没有本框架的正式实例资格。正确做法是保留它原来证明到哪里，重新申请更强资格时再补真正的新检验。","explanation":["原文定位：第225—232行；原文锚点 section-2-1-1；短引文：‘不因尚未转换成G-instance而失去原来有依据的内容’。本题源切片逐字附后，讲解与原文分开。","这节防止两种相反误用。第一种是把过去的探索或历史重建改写为预注册确认；第二种是因过去没有今日的表格，就把可定位史料和研究结论全部清零。原文允许研究设计实际支持的描述、解释或有限因果结论保留，禁止补造结果前合同。","“既有发现→新问题／模型来源→新合同→新材料检验”是一条可行接续。独立材料、后续时间窗或恰当复制可以提供新评价机会，但独立性要说明：不能先用全部资料调完模型，再把其中一段改称从未看过的验证集。后续窗口也仍要检查对象和测量变化。","如果没有可行新检验，就写清已有领域结论及待检关系，而不是把它挤进G-instance。形式证明、文本解释和规范论证也可参与，但要使用各自的成立方式：公理与推导、版本与语境、价值前提与理由。它们彼此提供问题和约束，不互相冒充现实机制或授权。","本节借Snow案只检验“历史资料和当前资格可以并存”这一点。1855年文本中的现场调查、访谈和限制是可以批评的历史证据，不会因为没有当代G合同就失去内容；我们也没有据它重建不存在的结果前时间戳。"],"distinctions":[{"leftTitle":"领域证据","leftText":"按原有研究设计支持限定结论。","rightTitle":"G正式资格","rightText":"按本框架证据前合同获得的具体实例地位。"},{"leftTitle":"重新解释旧资料","leftText":"可以提出不同模型与问题。","rightTitle":"补造旧时预注册","rightText":"把事后发现伪装为结果前承诺，改变材料身份。"},{"leftTitle":"独立分析","leftText":"另一种算法可能发现实现问题。","rightTitle":"独立确认材料","rightText":"其评价未被同一模型选择过程预先使用；仍须说明来源与依赖。"}],"boundaries":["Snow的水暴露材料与拆泵柄效果是两个不同的因果问题。用前者有根据，不等于后者已被单独识别。","历史证据不必转换成G-instance才可讨论；同样，“历史上有名”不让任何具体因果叙事免于批评。","本讲未复核原始死亡登记簿或取得个体数据，案例依据Snow原作相关段落，而非重做历史流行病学研究。"],"questions":["1855年的调查没有G-instance记录，能否仍用作历史水暴露问题的材料？","研究者不能取得任何新资料，是否必须否定旧发现？","“拆泵柄后的发病下降”能否直接当作拆柄净效果？"],"diagramPath":"/reading-assets/S-2-1/figures/section-2-1-1.png","caseLinks":[{"title":"1854年伦敦Broad Street：保存证据，也保存问题差别","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"1854年伦敦Broad Street：保存证据，也保存问题差别","text":"Snow在1855年第二版中报告，他查询死亡登记并调查饮水习惯；1854年9月7日向教区提出情况，次日泵柄被移除。原作同时说明，停用井水之前发病已经大幅下降，无法据此确定当时井水仍有致病作用。这里保留“调查报告了什么”与“干预净效果是否被识别”的差别。","sourceLabel":"John Snow, On the Mode of Communication of Cholera, 1855, 2nd ed.","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷页39—41、51—52；The Cholera near Golden Square及The Pump-well in Broad Street两段","boundary":"这是作者当时的历史调查记述，不是本讲重新验证全部病因；材料可支持有限暴露解释，不能单凭前后顺序估计拆柄效果，也不构成现代G预注册。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.1.1","start_line":225,"end_line":232,"startLine":225,"endLine":232}],"outputId":"section-2-1-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：既有材料的形成方式已发生，今天不能倒改其事前／事后身份。","连接：评价证据的范围与评价某个框架的资格条件是两项问题，因此可以分别记录而不互相取消。","结论一：保留设计实际支持的领域内容，同时标明它没有自动取得G-instance正向支持。","结论二：如需新资格，先冻结新问题并用合适新材料评价；无可行新检验时保持领域结论与待检状态。","职责：来源给历史事实和研究设计，当前解释给映射与推论上限；规范和授权另有依据。"],"teachingExamples":[],"counterexamples":[{"identity":"real_counterevidence","text":"Snow本人指出停用井水前发病已明显下降，并说无法确定停用时井中是否仍有活跃致病物。","effect":"这限制“拆柄导致全部下降”的叙事，但不一并撤销其水暴露调查。","sourceIds":["snow-context"]}],"questionAnswers":[{"question":"1855年的调查没有G-instance记录，能否仍用作历史水暴露问题的材料？","answer":"可以，按其调查设计、记述和限制使用；不能虚构当年的G预注册，也不能自动授予本框架正式支持。","basis":"本节原文及上述公开推导"},{"question":"研究者不能取得任何新资料，是否必须否定旧发现？","answer":"不必。保留原先有据的领域结论，说明新的正式资格尚未建立。","basis":"本节原文及上述公开推导"},{"question":"“拆泵柄后的发病下降”能否直接当作拆柄净效果？","answer":"不能。需要反事实比较，并处理下降早已开始、人口迁出及资料限制等竞争解释。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-1/figures/section-2-1-1.png","alt":"历史／既有材料，保留真实研究身份；领域结论，按原设计限定支持；原有局限与反例，继续约束结论；发现引出新问题，不补造旧合同；新合同＋合适新资料，探索与评价分开；新实例的支持／未决，不倒改旧研究。概念图，依据2.1.1；Snow原作只作历史例，图中不表示已完成新的G实例。","caption":"概念图，依据2.1.1；Snow原作只作历史例，图中不表示已完成新的G实例。"}],"diagramBrief":"图分旧材料与新资格两路。切换“有／无合适新资料”时，下路可停在新问题，上路已有的有限支持仍保留。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"历史材料有明确日期、出处和自述限制，可直接显示领域证据与新框架资格不相互取消。"},"openQuestions":["若要以现代比较设计重新估计拆柄净效果，需要更完整的暴露、迁出、发病时点和可比反事实资料；本讲没有这些材料。"],"taskId":"S-2-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第205—238行；每节精确范围见sourceRefs","claim_support":["intro-02-part：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-f1","title":"Xikari 条件形式命题与九轴定义","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18—§4.19：981—1028行；F1精确定义985—988行；§5.2九轴1039—1059行","claim_support":["2.1.2：目标恢复的同表示恒定条件及静态恢复不自动动力闭合。","导语教学例：SP为九轴尺度剖面，非单一观察分辨率。"],"limits":["模型内条件命题和定义不提供外部经验支持。"],"access_status":"read"},{"id":"snow-context","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版印刷页39—41、51—52；Gutenberg文本The Cholera near Golden Square和The Pump-well in Broad Street","claim_support":["2.1.1：Snow记述死亡登记与饮水调查、9月7日面谈及次日移除泵柄。","2.1.1：原作承认停用前发病下降，无法确定停用时井水仍有致病作用。"],"limits":["只读并使用相关原作段落；未复核登记簿与个体数据。","调查记述不是现代随机干预，也不是本框架结果前G合同。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-1/lecture.md","sourcesPath":"/reading-assets/S-2-1/sources.json","sourceSlicePath":"/reading-assets/S-2-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-1/diagrams.md"},"2.1.2":{"title":"2.1.2　形式结论与经验实例的接续","lead":"数学可以严格回答“在这些假设下是否成立”；现实应用还要回答“这个对象是否满足这些假设”。两份答案可以一份确定、一份未决。","explanation":["原文定位：第233—238行；原文锚点 section-2-1-2；短引文：‘计算次数也不增加独立经验支持’。本题源切片逐字附后，讲解与原文分开。","形式命题先固定状态域、映射、目标、允许操作与逻辑前提。证明说明结论怎样由这些前提推出；有限域穷举检查所有声明情形；数值检查则还须交代精度、边界与实现误差。三者能互查错误，却不会凭计算生成新的现实样本。","跨入现实的接续要逐项完成：模型变量对应什么可观察量，测量和表示是否保留目标所需区别，哪些前提已有资料，误差与适用区间是否可接受，何种反例会推翻映射。原文§4.18—§4.19的F层尤其强调：静态恢复、动态闭合、干预可迁移不是同一命题。","形式反例足以推翻它命中的无条件推理。例如“一种汇总总能恢复每个分量”只要有一个明确数学反例就不成立，不必先到工厂或医院做实验；但反例不说明现实中的每一种汇总都没用。目标改为总量时，同一个表示可能完全足够。","现实采用有六份独立责任：形式可行；算法存在；在预算内可计算；资料及时可得；实际执行正确；有权采用。上一步通过不蕴含下一步通过。知道一个决策规则存在，可能既算不完，也拿不到及时输入；即使能算能做，也不自动取得对人的处置权。"],"distinctions":[{"leftTitle":"证明成立","leftText":"在声明公理和语义中推论有效。","rightTitle":"现实适配成立","rightText":"变量映射和前提在目标对象上有足够材料。"},{"leftTitle":"穷举四个状态","leftText":"覆盖这一个有限模型的全部状态。","rightTitle":"四个现实观测","rightText":"来自世界的资料，有抽样、测量和依赖问题。"},{"leftTitle":"算法存在","leftText":"有规则可求答案。","rightTitle":"及时、正确且有权执行","rightText":"计算预算、资料、实施和权限分别满足。"}],"boundaries":["数学反例已经否定“任意汇总均可恢复任意细节”，但没有否定目标为总量时的充分性。","若允许读取额外信息，如x₂，就已改变允许操作与表示合同，不能把新的可恢复性算成旧合同的成功。","有限域穷举必须完整列域；随机抽到大量状态仍不是对无限域的证明。数值近零也不自动成为精确等于零。"],"questions":["运行同一四状态穷举一百万遍，增加了一百万份独立经验支持吗？","上述反例中，允许额外读取x₂后能恢复x₁吗？","一个规则已被证明存在，能据此宣布次日可以自动上线吗？"],"diagramPath":"/reading-assets/S-2-1/figures/section-2-1-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.1.2","start_line":233,"end_line":238,"startLine":233,"endLine":238}],"outputId":"section-2-1-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["数学前提：状态域X={0,1}²；表示π(x₁,x₂)=x₁+x₂；目标q(x₁,x₂)=x₁；恢复器g只能读取π。","取x=(0,1)、x′=(1,0)，则π(x)=π(x′)=1，而q(x)=0、q(x′)=1。","若存在对所有状态正确的g，则g(1)须同时等于0和1，矛盾。因此在该完整状态域和该表示下不存在精确恢复q的单值函数。","改变目标为qΣ=x₁+x₂时，gΣ(z)=z即可精确恢复。结论是目标相对的，不是所有聚合都失败。","现实责任：若把x₁、x₂解释为真实量，须另证状态域、测量、输入可用性与允许操作；上述四状态证明不提供现实发生频率或干预效果。"],"teachingExamples":[{"title":"数学构造：同一个和，两个不同的第一分量","text":"四状态为(0,0)、(0,1)、(1,0)、(1,1)；其π依次为0、1、1、2，q依次为0、0、1、1。在π=1这组中目标不恒定，所以只读和无法恢复第一分量。若目标改为和，则每个表示值都直接给答案。这是完整有限域上的精确整数计算。","assumptions":"域只有这四个状态，恢复器单值且只读取π，不使用身份标签或额外测量。","boundary":"这是数学可恢复性例，不是现实效果、人物类型或统计误差估计；它不能证明某现实系统恰好满足模型。"}],"counterexamples":[{"identity":"constructed_boundary","text":"数学边界：在原四状态域上q=x₁不可恢复；若合法域缩为{(0,0),(1,1)}，同一π的每个值只对应一个状态。","effect":"缩小合法域改变了前提，可恢复性随之改变；不能把原域的失败泛化到所有受限域。","sourceIds":["theory"]}],"questionAnswers":[{"question":"运行同一四状态穷举一百万遍，增加了一百万份独立经验支持吗？","answer":"没有。它可以帮助发现实现错误，但仍检查同一模型，未产生新的现实观测。","basis":"本节原文及上述公开推导"},{"question":"上述反例中，允许额外读取x₂后能恢复x₁吗？","answer":"能，x₁=π−x₂；但这是扩大了输入条件，不是推翻原来的“只读π”不可恢复结论。","basis":"本节原文及上述公开推导"},{"question":"一个规则已被证明存在，能据此宣布次日可以自动上线吗？","answer":"不能。还需算法、预算、资料时效、实施正确性及采用权限，各自有证。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-1/figures/section-2-1-2.png","alt":"状态 x=(0,1)，目标 q=0；共同表示 π=1，只允许读取这个和；状态 x′=(1,0)，目标 q=1；恢复第一分量，g(1)要求同时为0和1；恢复总量，gΣ(1)=1 即可。数学构造图，精确域{0,1}²；不表示任何现实样本或效应，依据2.1.2与F1的目标相对性。","caption":"数学构造图，精确域{0,1}²；不表示任何现实样本或效应，依据2.1.2与F1的目标相对性。"}],"diagramBrief":"将两个同表示状态合并，显示恢复冲突。交互可切换目标“第一分量／总量”或合法域，变更必须同步写明前提。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节直接讨论形式有效性与经验接续。完整有限数学构造足以检验无条件推理；不附加无关史实来充当实证。"},"openQuestions":[],"taskId":"S-2-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第205—238行；每节精确范围见sourceRefs","claim_support":["intro-02-part：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.1.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-f1","title":"Xikari 条件形式命题与九轴定义","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"§4.18—§4.19：981—1028行；F1精确定义985—988行；§5.2九轴1039—1059行","claim_support":["2.1.2：目标恢复的同表示恒定条件及静态恢复不自动动力闭合。","导语教学例：SP为九轴尺度剖面，非单一观察分辨率。"],"limits":["模型内条件命题和定义不提供外部经验支持。"],"access_status":"read"},{"id":"snow-context","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版印刷页39—41、51—52；Gutenberg文本The Cholera near Golden Square和The Pump-well in Broad Street","claim_support":["2.1.1：Snow记述死亡登记与饮水调查、9月7日面谈及次日移除泵柄。","2.1.1：原作承认停用前发病下降，无法确定停用时井水仍有致病作用。"],"limits":["只读并使用相关原作段落；未复核登记簿与个体数据。","调查记述不是现代随机干预，也不是本框架结果前G合同。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-1/lecture.md","sourcesPath":"/reading-assets/S-2-1/sources.json","sourceSlicePath":"/reading-assets/S-2-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-1/diagrams.md"},"2.2":{"title":"2.2　命题角色与论证责任","lead":"一句“这个系统有效，所以应当使用”至少混合了对象定义、效果判断、价值选择和行动权限。先拆句，才知道每一部分该拿什么来支持。","explanation":["原文定位：第239—264行；原文锚点 section-2-2；短引文：‘编号组织论证责任，不表示各类具有相同的真值条件’。本题源切片逐字附后，讲解与原文分开。","D回答“在这里这个词指什么”。给“结构”“修复”规定语义，有助于一致判断，却不证明世界中存在相应对象或已经修好。G回答具体经验问题：什么对象、什么比较、哪个条件下的差异是否超过阈值。G1—G4是问题族，实例才承载具体事实断言；事实可能为真而当前支持不足，也可能程序完整却因模型错误而结论有误，正式资格不能定义世界。","E约束知道多少：测量盲区、竞争解释、残差和跨尺度迁移条件应保留。N公开价值选择：保护什么、限制什么。这两者有不同职责；承认认识局限不自动证明某种价值，而选择保护某人也不自动证明对其处境的每条描述都正确。O把冻结、审计、规范登记、授权、方案比较、受限执行、复核、停止、撤回、补救组织成程序；它约束可怎么做，不代替事实依据。","H最容易读错。它是人类领域的适配标记，而不是与定义、经验、规范完全互斥的第六种真理。H1、H4、H5是逐案需要证据的经验假设；H2是操作分型；H3是制度写回分类；H6是规范边界。不能因为它们同属H，就把全部当作先验人性公理，更不能把人的意义与制度规则倒写成所有自然过程的根。","F是条件形式命题，在明确状态域、映射、目标、操作集和数学前提下由证明成立。数学反例可以击破越过前提的普遍推理；现实是否满足前提仍要取证。原文§4.18的F1—F5以及§4.19的任务族和动态精化，分别展示恢复、动力学、干预、组合及近似边界，不能只因都是公式便认定用途一样。","C不是再增加一类与D、G等并排的世界事实，而是对结果怎样登记、在何种机制条件下使用的合同；其中C12承担规范程序桥接。共同方法约束也不是新增世界定律。给某结论贴上更多编号，只增加可定位性，不增加独立证据。","行动最小桥接式包含六项：描述或解释结论、明示规范前提、当前证据、合法授权、行动上限、停止或撤回条件。缺任一项，相关现实处置应停住。仍可继续描述、提出候选、补证、不行动，或提出可逆试探方案；“提出方案”本身并未授权实施。它是一组必要审查项，不保证列全就自动满足所有领域的法律、专业或安全要求。"],"distinctions":[{"leftTitle":"语义成立","leftText":"某对象按定义符合分类。","rightTitle":"经验成立","rightText":"对象及相应关系由材料支持，非靠定义生成。"},{"leftTitle":"H领域标记","leftText":"提示在人类对象上追加哪类合同。","rightTitle":"逻辑角色","rightText":"要进一步判断是经验、分类、程序还是规范。"},{"leftTitle":"C结果／机制合同","leftText":"限定既有依据的使用。","rightTitle":"额外证据","rightText":"需要独立材料，不能由编号增加。"},{"leftTitle":"解释／诊断","leftText":"说明可能发生什么及为何。","rightTitle":"处置权","rightText":"有资格对目标采取指定行动；不能从理解深度推出。"}],"boundaries":["一段证明有效，不代表测量映射真实；一道程序门通过，不代表实体因果关系存在。","行动桥接是最小必要条件集合，不是完备的行政、医疗或法律许可书；本讲不进行现实诊断或处置。","价值前提可被批评和修订，但不能通过把它改称“客观机制”来免去理由公开。"],"questions":["“H6是规范边界，所以H1也不需要经验资料。”这一步为什么不成立？","一个正式支持实例是否把效应的事实真假定义了出来？","如果缺少停止条件，但方案被认为很有益，桥接式允许直接实施吗？"],"diagramPath":"/reading-assets/S-2-2/figures/section-2-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.2","start_line":239,"end_line":264,"startLine":239,"endLine":264}],"outputId":"section-2-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：定义约定、经验断言、数学推论和价值承诺有不同成立方式，不能用一个统一“已证明”替代。","拆解：将复合句分成可识别的子句，给每句注明所问对象与角色；对H另写其经验、操作、分类或规范性质。","连接：定义要求语义一致，经验需要设计与材料，形式需要前提与证明，规范需要价值与理由，行动还需权限和停止机制。满足其中一项不完成其余项。","结论：从“解释可信”到“可以处置”必须补齐行动桥接；缺项只阻断依赖它的处置，不自动撤销独立成立的事实或证明。","证据责任：不能以框架自己的D、C或方法说明充当对象事实；不能把程序合规或价值正当说成因果机制已被证明。"],"teachingExamples":[{"title":"教学构造：拆开“准确，所以应强制采用”","text":"设一句话为：“我们把预测误差低于e的工具定义为准确；工具A在指定测试集达到该标准；因此应强制所有人使用，研发者有权直接部署。”第一句是D式语义约定；第二句是有待核测试设计与范围的经验断言；第三句中的“应强制”需要N式价值理由，部署资格需要授权及O程序，均未从误差结果推出。若证明某算法误差界，则是F式条件结论，仍要核现实满足假设。","assumptions":"工具、阈值e和测试均是假设，不表示真实产品或已做试验。","boundary":"只用于辨别论证职责；不能据此认定任何工具可靠、合理或获准部署。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：规定“凡被称为修复的操作都是有益操作”，再用某操作被登记为修复来证明它有益。","effect":"把规范结论塞进定义后循环取证；应分开预设目标、观察结果及价值评价。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学边界：某人能最准确预测团队反应，便自称拥有调整成员岗位的权限。","effect":"知识优势不生成授权；停在解释或提案，不能越过权限边界。","sourceIds":["theory"]}],"questionAnswers":[{"question":"“H6是规范边界，所以H1也不需要经验资料。”这一步为什么不成立？","answer":"H是领域适配标记，不是统一逻辑类型。H1是逐案取证的经验假设，H6的规范身份不能移植给它。","basis":"本节原文及上述公开推导"},{"question":"一个正式支持实例是否把效应的事实真假定义了出来？","answer":"没有。实例与程序管理我们能给多少支持；世界中的效应是否存在，是它试图回答而非凭登记创造的问题。","basis":"本节原文及上述公开推导"},{"question":"如果缺少停止条件，但方案被认为很有益，桥接式允许直接实施吗？","answer":"不允许。相关处置应暂停，可补齐方案、提出可逆试探或不行动；有益判断也需自己的证据与规范理由。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-2/figures/section-2-2.png","alt":"D／E，语义与认识边界；G／H中的经验条款，比较、材料、失败方式；F，数学前提与证明；描述／解释的有限结论，不能独自授权；N＋当前证据＋合法授权，还需行动上限；O＋停止／撤回条件，相关现实处置审查。责任示意图，依据2.2；H不是单一逻辑类型，C是使用合同。图中箭头不表示经验因果。","caption":"责任示意图，依据2.2；H不是单一逻辑类型，C是使用合同。图中箭头不表示经验因果。"}],"diagramBrief":"上层展示三种不同依据，下层展示行动桥接。切换“授权缺失”只阻断处置，不把已有数学证明或独立事实一并抹除。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节给出论证角色与必要桥接条件，教学拆句直接显示非等价关系；真实案例不能独自验证分类约定，故不强配史实。"},"openQuestions":[],"taskId":"S-2-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第239—264行；每节精确范围见sourceRefs","claim_support":["2.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-2-2/lecture.md","sourcesPath":"/reading-assets/S-2-2/sources.json","sourceSlicePath":"/reading-assets/S-2-2/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-2/diagrams.md"},"2.3":{"title":"2.3　四类依赖必须分开","lead":"“需要它”可能指推不出来、不能发布、只适用于某领域，或行动受它约束。这四个意思要分开画，否则会把程序当成原因，把规范当成证据。","explanation":["原文定位：第265—277行；原文锚点 section-2-3；短引文：‘只有推理硬前提进入根—推论的无环图’。本题源切片逐字附后，讲解与原文分开。","inferential_requires是推理硬前提：在这条公开论证中，缺了该前提就不能推出所写结论。例如要推出“所有同表示状态有同一目标值，因此存在目标恢复器”，同表示状态目标恒定这一前提不能删。它可以进入根—推论的有向无环图，方向应统一解释为从前提到依赖它的结论。","protocol_requires是方法门：证据、因果、类比、来源或领域分类合同规定这次判断怎样记录、检查与发布。缺门会失去相应发布资格，但门不是世界中的新增经验原因。事前冻结给按原问题评价提供固定依据，仍须核对实际执行及偏离；不是冻结文件令物理效应发生。","specializes是特化：把一般命题限定到某领域、对象或子型，需要列出额外条件和适用范围。它不自动证明该领域对象存在，也不把分类条款变成支持材料。applies_to则记规范或程序约束谁、何种行动或命题；隐私规则适用于某资料，并不能反向证明资料里声称的事实为真。","原表把四类关系分别标为“能、不能、不能、不能”进入推理无环图。这不是说后三类不重要，而是要求分图或分层保存不同意义。发布流程可以包含复核、退回、再提交的循环；那是程序结构，不应为了画成一张DAG就把程序循环误读为经验推理的循环。","一个案例可以同时有多种关系，关系应逐条记录。例如某个事实论断在推理上用到比较数据，在发布上受冻结要求，在范围上限于某子型，在行动上受规范约束。不能只放一条没有类型的“依赖”边。若协议门失败，先撤去相应发布或支持资格；若硬前提失败，则失去依赖该前提的推论依据。两者影响对象不同。"],"distinctions":[{"leftTitle":"推理上必要","leftText":"少此前提，这条论证不成立。","rightTitle":"发布上必要","rightText":"程序不满足，不能按该级别发布；不直接改变世界里的真假。"},{"leftTitle":"领域特化","leftText":"添加范围和条件。","rightTitle":"经验支持","rightText":"材料支持特化对象中的具体关系，两者不能互换。"},{"leftTitle":"规范适用","leftText":"规定对谁、何事须受约束。","rightTitle":"事实验证","rightText":"判定具体描述是否有据；受保护不等于描述已证实。"}],"boundaries":["无环图限定的是论证依赖，不禁止现实系统具有反馈、也不禁止操作流程有复核循环。","不能因方法门不在推理DAG中就将其删除：它仍决定相应结论能否以某种身份发布和使用。","若一个原先当作程序要求的条件也被写入数学命题前提，应分别登记该命题的形式角色与发布门角色；同一文字的两次使用不能悄悄混成一条边。"],"questions":["来源合同未满足，但一个给定前提下的数学推导仍有效，应怎样记录？","“隐私规则适用于这份访谈，所以受访者的全部说法为真”错在哪条边？","一个专用于人类组织的规则能否经specializes边回推成所有自然系统规律？"],"diagramPath":"/reading-assets/S-2-3/figures/section-2-3.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.3","start_line":265,"end_line":277,"startLine":265,"endLine":277}],"outputId":"section-2-3","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：不同“依赖”具有不同反事实问题：删掉它，是推理断裂、发布不合格、范围改变，还是行动不被允许？","分类：对每条边逐一回答上述问题，并保留关系类型；一个节点可参与多类关系，但不能用同名合并边的含义。","连接：只有把结论的成立作为被解释项时，推理硬前提才进入根—推论DAG。方法、特化和适用关系另存。","结论：分层图避免由发布要求推出现实机制，或由规范适用推出现实事实；还能在前提受损时确定应暂停哪条推论。","责任：类型登记不是证明本身；每条硬前提仍须有相应推导或材料，方法门也须按实际合同检查。"],"teachingExamples":[{"title":"教学构造：恢复器的一句结论与四种关系","text":"命题P：若π(x)=π(x′)必有q(x)=q(x′)，则能在π的像上定义g，使q=g∘π。给g(z)取任一原像的q值；上述恒定前提使选择不同原像不改结果，这是推理硬前提。要求公开状态域及检查记录是方法门；限定X为有限集是一个特化；某机构规定不得用g对人作未授权处分是规范适用。后面三项不能被当成证明q恒定的证据。","assumptions":"只讨论集合、映射和给定规范的教学情境，未称任何机构实际采用此规则。","boundary":"形式例不提供现实测量充分性；公布检查记录也不创造数据或授权。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：“必须经过伦理审查才准发布，所以伦理审查是实验所观察效应的经验原因。”","effect":"把protocol_requires或applies_to错读成因果机制。程序可约束研究行为，但这条许可关系本身不能证明目标物理或社会效应。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学边界：程序图有“复核失败→修改→重新复核”，据此宣称整套论证循环无效。","effect":"程序循环不等于推理循环。应单独检查硬前提DAG是否循环；不能跨图层套用同一判断。","sourceIds":["theory"]}],"questionAnswers":[{"question":"来源合同未满足，但一个给定前提下的数学推导仍有效，应怎样记录？","answer":"保留该形式推导的条件有效性；缺来源可能阻断现实映射或发布资格，不能仅据此宣判数学推导为假。","basis":"本节原文及上述公开推导"},{"question":"“隐私规则适用于这份访谈，所以受访者的全部说法为真”错在哪条边？","answer":"applies_to只给保护和使用约束，不能反向充当事实证据。","basis":"本节原文及上述公开推导"},{"question":"一个专用于人类组织的规则能否经specializes边回推成所有自然系统规律？","answer":"不能。特化是收窄范围并追加条件，不能反向扩大为普遍世界断言。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-3/figures/section-2-3.png","alt":"推理硬前提，inferential_requires；结论的推理依据，仅此类进入推理DAG；方法门，protocol_requires；领域特化，specializes；适用范围／发布／行动，分别登记，不混边；规范或程序适用，applies_to。类型图，依据2.3原表；只有左上推理关系属于根—推论DAG，其余箭头不是经验原因。","caption":"类型图，依据2.3原表；只有左上推理关系属于根—推论DAG，其余箭头不是经验原因。"}],"diagramBrief":"图的箭头必须显示关系类型。交互可只显示推理层，隐藏其余边但不删除其合同；选中一条边显示缺失时影响推理、发布、范围还是行动。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节规定依赖关系的语义，使用明确数学例和条件反例即可验证误推；不把不相关历史材料当作图类型的实证。"},"openQuestions":[],"taskId":"S-2-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第265—277行；每节精确范围见sourceRefs","claim_support":["2.3：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-2-3/lecture.md","sourcesPath":"/reading-assets/S-2-3/sources.json","sourceSlicePath":"/reading-assets/S-2-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-3/diagrams.md"},"2.3.1":{"title":"2.3.1　共同方法内核的分层责任","lead":"两份理论可以共用一套认真记录和推理的要求，却不能互相给对方“盖真章”。对齐的是每一层的职责和条件，不是名字或编号。","explanation":["原文定位：第278—292行；原文锚点 section-2-3-1；短引文：‘彼此不充当权威来源或双重经验证据’。本题源切片逐字附后，讲解与原文分开。","这一节处理本框架与《世界模型》的互操作边界：可以共享方法责任，但必须保留各自对象、论证和运行形态。“可以共享”不是已经完成所有版本的对应验证。当前材料提供了Xikari的现行文本，未提供可定位版本的《世界模型》全文，因此本讲解释本段声明，不声称已经核实另一文本。","原表第一层“定义”固定对象与术语的可判定语义；它可以帮助两份文本知道在谈什么，却不证明这些对象在现实存在。第二层“共同方法约束”管理表示、材料身份与推理，例如不把模拟当观察、不把方法门当经验原因；共同遵守它们并不新造一条自然或社会规律。","第三层F在数学前提下回答必然得到什么；证明的效力由域、映射、目标、操作与假设承担，跨文本出现相同定理名称不能省去前提对应与证明核对。第四层G组织具体经验问题，真正的支持来自有对象、比较、失败方式与资料的实例；两本文本复述同一研究并不形成两次独立观察。","第五层C问现有依据允许登记和使用什么。它依赖相关结果、附加机制条件和适用窗，不能因为共同内核有某条规则就补出缺失的机制连接。第六层治理不变量约束发布、评价、暂停与行动；它们限制权力的使用，不作为研究对象产生变化的额外原因。","D、G、C编号服务于稳定引用，共同内核的中文编号服务于跨文本对齐。两者都不是合同的替身。真正核对时，应把完整语义、前提、证据身份、目标与失败规则并排比较：同名而条件不同应记录差异，异名而条件对应也可建立有依据的映射。","本节承接2.2的论证角色和2.3的依赖分层，防止“我在另一文本也说过，所以多一份支持”的循环。共同方法可提高互操作的清晰程度；框架在某类现实任务上是否更有用，仍是另一个需要比较设计和材料的问题。"],"distinctions":[{"leftTitle":"共同方法约束","leftText":"双方如何记录和使用依据。","rightTitle":"共同世界定律","rightText":"关于现实规律的经验或形式主张，需相应证明或资料。"},{"leftTitle":"稳定编号","leftText":"便于定位合同。","rightTitle":"完整合同","rightText":"语义、前提、适用窗、证据及失败规则；不能由编号代替。"},{"leftTitle":"两份文本同意","leftText":"可能源于共享定义或同一材料。","rightTitle":"两份独立经验支持","rightText":"需要真正不同且与主张相关的资料或设计，不能按文件数计。"},{"leftTitle":"可互操作的声明","leftText":"提出核对责任和可能的对接方式。","rightTitle":"已验证的互操作","rightText":"实际版本、映射、运行与测试材料均可核查。"}],"boundaries":["未提供另一文本的可定位版本，故不能声称双方术语完全同义、全文一致或已经共享同一运行内核。","六层不是由低到高自动升级的证据梯子。一个定义不会经过方法层就自动变成经验事实，治理层也不比经验资料更能证明因果。","一处跨文本对应失败应限制该项连接；若只是名字不同，不应据此否定另一个文本已有独立依据的所有结论。"],"questions":["两份文本使用同一个中文编号，是否能直接合并其条款？","共同采用“模拟不回写观察”这一要求，会给某模拟增加经验真实性吗？","缺少另一文本时，本节还能完成什么，不能完成什么？"],"diagramPath":"/reading-assets/S-2-3-1/figures/section-2-3-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.3.1","start_line":278,"end_line":292,"startLine":278,"endLine":292}],"outputId":"section-2-3-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：两个文本分别有其对象域、运行形式和论证，重复命名不意味着前提与语义相同。","连接一：逐层比较定义、方法、F、G、C及治理，能够区分“语义相容”“形式实例”“经验支持”和“权力限制”。","连接二：同一来源的重复使用没有增加独立资料，所以不能把跨文本一致意见加总为双重经验支持。","结论：共享方法责任可以成立为互操作要求；具体文本是否满足对应关系，要在获得正确版本后逐项核对。","职责与现有限制：现行Xikari原文支持本节如何自述接口；它不能独自证明《世界模型》的实际内容，也不能证明互操作已经成功运行。"],"teachingExamples":[{"title":"教学构造：同名“闭合”须逐条对齐","text":"假设文本甲的“闭合”只要求当前目标q可由表示π恢复；文本乙的“闭合”还要求每个允许动作后表示可自行更新。两者名字相同，但乙加入动态与动作条件。对齐时应记录“甲是静态恢复要求，乙另有动态要求”，不能直接互换。反过来，两个不同名称若前提、域和结论逐项等价，才可能建立形式映射。","assumptions":"甲乙是为教学自拟的两份文本，不指称《世界模型》的实际内容。","boundary":"例子展示对齐方法，不能证明现实跨书对应或任何框架的经验有效性。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：两份讲义都引用同一次研究，于是报告“有两项独立研究支持”。","effect":"重复转述未增加原始资料；只能记共同来源与各自解释，不能扩大独立支持计数。","sourceIds":["theory"]},{"identity":"unresolved_boundary","text":"未获得《世界模型》的指定版本，却把Xikari关于共享方法的声明当作双方完整一致的证据。","effect":"对另一文本的实际对应保持未核；当前可以解释Xikari的自述，但不能代写对方内容。","sourceIds":["theory"]}],"questionAnswers":[{"question":"两份文本使用同一个中文编号，是否能直接合并其条款？","answer":"不能。必须核对完整定义、前提、对象域、失败条件与运行含义；编号只是定位工具。","basis":"本节原文及上述公开推导"},{"question":"共同采用“模拟不回写观察”这一要求，会给某模拟增加经验真实性吗？","answer":"不会。这条要求反而限制材料的使用身份；真实支持仍需外部观察和桥接。","basis":"本节原文及上述公开推导"},{"question":"缺少另一文本时，本节还能完成什么，不能完成什么？","answer":"能解释当前文本的六层责任与互操作规则；不能核实另一文本实际内容、两书等价性或真实运行成功。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-3-1/figures/section-2-3-1.png","alt":"定义，对象和术语指什么；共同方法约束，表示／身份／推理；条件形式命题 F，前提与证明；经验问题族 G，实例／比较／失败；结果与机制合同 C，依赖／条件／适用窗；治理不变量，发布／暂停／行动。六格责任图，依据2.3.1原表；位置不表示等级或因果顺序，未声称已核另一文本。","caption":"六格责任图，依据2.3.1原表；位置不表示等级或因果顺序，未声称已核另一文本。"}],"diagramBrief":"六格对应六种核对工作，不画自动升级箭头。交互可选择文本版本逐格展示完整合同差异；当前另一版本未给，应该显示待核而非默认相同。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是跨文本接口与论证职责说明，不适合拿不相干史实验证；当前缺少另一文本的指定版本，故不伪造已完成的真实跨书案例。"},"openQuestions":["如需执行实际互操作比较，需要《世界模型》的作者、完整版本、日期及对应条款；本讲只解释现有Xikari原文的要求。"],"taskId":"S-2-3-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第278—292行；每节精确范围见sourceRefs","claim_support":["2.3.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-2-3-1/lecture.md","sourcesPath":"/reading-assets/S-2-3-1/sources.json","sourceSlicePath":"/reading-assets/S-2-3-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-3-1/diagrams.md"},"2.4":{"title":"2.4　因果契约","lead":"看到变化发生在某行动之后，还不够回答“行动造成了多少变化”。反过来，某个比较能回答总效果，也未必已经知道每一个中间环节。","explanation":["原文定位：第293—298行；原文锚点 section-2-4；短引文：‘效应有限识别、具体机制未决’。本题源切片逐字附后，讲解与原文分开。","因果合同先把处理版本和结果说清。例如“停用某水源”不同于“发布建议”，当日发病不同于当日死亡，局部人群不同于全城居民。再固定对象、人群、时间窗、尺度与效应目标；没有这些，两个研究声称“有效”也可能回答完全不同的问题。","比较为什么识别目标，是因果主张的中心。共同输入可同时影响处理与结果；自我选择使接受处理者原本就不同；失访改变所见样本；测量变化改变记录；结果反过来影响处理；一个单位的处理还可能影响他人。相关者逐项处理，不是无论任务如何都机械加控制变量。","识别某个总效应与识别指定结构通道有不同负担。若声称A经M影响Y，应有对应层级的时序和机制链，以及能区分替代解释的阻断、替换或满足识别条件的自然变异。跨层还要核D3/E5桥接。只有总效应的设计不应被迫先穷尽一切微观过程；但也不能据总效应补写未经检验的中介。","因果强度、机制分辨率和外推范围三者分别评价。某比较在限定窗口内较可信，不等于能精细解释全部通道，也不等于能搬到所有人群。反方向的提醒同样重要：两个机制可抵销，净总效应接近零不表示每条机制都为零。","下节2.4.1进一步区分“获得机会”“接受干预”“制度扩张”等估计目标，2.4.2则用精确反例说明，分别估准两段平均作用仍不足以把它们串成整链效果。"],"distinctions":[{"leftTitle":"时间先后","leftText":"A发生在Y之前，是因果时序所需的一部分。","rightTitle":"因果识别","rightText":"能排除或控制相应竞争解释，支持指定反事实比较。"},{"leftTitle":"总效应","leftText":"处理改变后终端结果的综合变化。","rightTitle":"指定机制","rightText":"通过哪条通道、在哪些共同条件下产生变化。"},{"leftTitle":"有限识别","leftText":"在某人群、窗口和假设内能回答问题。","rightTitle":"广泛外推","rightText":"新对象和尺度下仍成立，需额外依据。"}],"boundaries":["Snow的表是“最终致死病例按发病日排列”和“死亡日计数”的两列，不是全部感染或全部发病人数。不能混用其分母和事件时钟。","Snow所述停用前下降限制单纯前后归因，不证明移除泵柄毫无作用；缺少可比反事实，零效果也不能自动识别。","机制尚未识别时保留总效应的有限结论；总效应未显著时也保留有独立依据的局部过程知识。"],"questions":["一个随机比较支持某处理的总效应，但没有测量中介。能否报告总效应？","总效应接近零，是否可以写“所有通道均不存在”？","Snow案中，早于移柄的发病下降能证明什么？"],"diagramPath":"/reading-assets/S-2-4/figures/section-2-4.png","caseLinks":[{"title":"Broad Street：把暴露证据与拆柄净效果分开","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"Broad Street：把暴露证据与拆柄净效果分开","text":"1854年Broad Street疫情的Snow表I，将致死病例按发病日与死亡日分别排列：9月1日的致死病例发病数为143，9月7日为28，9月8日移除泵柄。原作还指出人口迁出及停用前下降。本节新增观察点是事件时钟与反事实：这些记录不能让“移柄后的低值”独自成为移柄净效果。","sourceLabel":"Snow 1855第二版，Table I及作者说明","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷页49表I；页50—52表后说明；页40记9月7日面谈及次日拆柄","boundary":"表内有发病日不明者，且只统计最终致死病例；本文不估计所有感染数、不重建控制组，也不推出移柄零效果。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.4","start_line":293,"end_line":298,"startLine":293,"endLine":298}],"outputId":"section-2-4","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：因果问题包含处理与结果的反事实比较；只看到同一条实际路径，不能直接读出未实施路径的结果。","连接：一个可信设计须说明为何可比较组、时期或变异能代表目标反事实，并处理与该设计有关的混杂、选择、干扰和测量问题。","结论：可以按识别条件报告限定总效应；指定机制还要另有通道区分证据，外推还要另有桥接。","反向检验：总效应为零可能来自路径抵销；局部路径存在也可能没有在同一对象、窗口接通。","证据责任：历史文献能支持其实际观察与比较，不能因叙事连贯就自动提供净效果估计。"],"teachingExamples":[{"title":"教学数学构造：两条路径恰好抵销","text":"设a∈{0,1}，一条路径给结果增加a，另一条路径给结果减少a，终端y(a)=a−a=0。每条构造路径都随a变化，但y(1)−y(0)=0。它说明“净效应零→所有机制不存在”这一无条件推理不成立。","assumptions":"两项都是同单位、同对象、同窗口的可加分量，且函数完全给定。","boundary":"抵销由假设给出，不是在任何现实系统中估计到的事实；换单位或加交互项须另算。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Snow表I记载9月1日致死病例发病数143、9月7日28；9月8日才移除泵柄。作者同时承认停用前已大幅下降。","effect":"不能把此前已经发生的下降全部归给后来的移柄行动；也不能反推移柄的净效果必为零。","sourceIds":["snow-table"]}],"questionAnswers":[{"question":"一个随机比较支持某处理的总效应，但没有测量中介。能否报告总效应？","answer":"可以，在设计假设与适用范围内报告，并明确具体机制未决；不能补造中介链。","basis":"本节原文及上述公开推导"},{"question":"总效应接近零，是否可以写“所有通道均不存在”？","answer":"不可以。路径可抵销，也可能测量或精度不足；需分别检查所声称的通道。","basis":"本节原文及上述公开推导"},{"question":"Snow案中，早于移柄的发病下降能证明什么？","answer":"它反对把全部下降归因于后来移柄的简单叙事；它本身没有识别移柄的净效果。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-4/figures/section-2-4.png","alt":"1854年9月1日，致死病例发病数 143；9月7日，致死病例发病数 28；9月8日，移除Broad Street泵柄；计数对象，最终致死病例的发病日；竞争解释，迁出／暴露变化等；尚缺反事实比较，不报告移柄净效果。来源：Snow 1855，表I pp.49及说明pp.50—52；框间距离非时间比例，箭头只表示先后，不表示因果。","caption":"来源：Snow 1855，表I pp.49及说明pp.50—52；框间距离非时间比例，箭头只表示先后，不表示因果。"}],"diagramBrief":"静态事件时间图，数字按原表“Fatal Attacks”列读取，并说明不是全部病例。可切换发病日／死亡日，但须显示不同列与未知日期，不把下降曲线当净干预效应。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一历史案在此只用于识别时序、事件定义与干预归因边界，不重复上一题的资格问题。"},"openQuestions":["若要估计移柄净效果，还需可比反事实、迁出和水暴露变化等材料；本讲不把历史表格改造成随机实验。"],"taskId":"S-2-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第293—314行；每节精确范围见sourceRefs","claim_support":["2.4：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-table","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版，印刷页40、49表I、50—52","claim_support":["2.4：9月1日致死病例发病数143、9月7日28；9月8日移除泵柄。","2.4：作者区分发病时点和死亡时点，并说明迁出与移柄前下降。"],"limits":["致死病例不等全部病例；发病时点有估算和未知。","只核相关原作段落与表，不构成净干预效果重估。"],"access_status":"partially_read"},{"id":"oregon-abstract","title":"Finkelstein et al., The Oregon Health Insurance Experiment: Evidence from the First Year","url":"https://www.nber.org/papers/w17190","source_type":"primary","version_or_date":"2011-07，DOI 10.3386/w17190","locator":"NBER Working Paper 17190，官方摘要前两句；检索返回官方正文","claim_support":["2.4.1：2008年Oregon抽签给未参保低收入成年人申请Medicaid的机会。"],"limits":["当前直接网页和PDF打开返回403；仅据官方检索返回摘要，不声称全文已读。","仅支持设计事实，不认证本讲教学公式在该研究中的全部识别条件或具体健康结果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-4/lecture.md","sourcesPath":"/reading-assets/S-2-4/sources.json","sourceSlicePath":"/reading-assets/S-2-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-4/diagrams.md"},"2.4.1":{"title":"2.4.1 估计目标与机制责任","lead":"先问“究竟改变了什么”，再谈效果。抽签给机会、本人选择接受、制度全面扩张，面对的是不同反事实，不能共用一个“处理效应”标签。","explanation":["原文定位：第299—306行；原文锚点 section-2-4-1；短引文：‘给某人一个机会、某人实际接受干预、整个制度扩张，是不同的处理’。本题源切片逐字附后，讲解与原文分开。","设Z表示获得机会，D表示实际接受，Y是结果。比较随机Z可以在相应设计条件下识别“给予机会”的效果；直接比较D=1与D=0却可能混入自我选择。即使Z改变了D，也要追加排除限制等条件，才能把机会效果解释为接受干预的某种局部效果。某项额外假设受损时，应撤去依赖它的解释，不自动撤销仍可信的随机机会比较。","总体平均、某类依从者的局部平均、每个个体的结果，回答不同问题。局部效果可能只适用于因机会变化而改变接受状态的人；不能直接推广到不愿接受者、必然接受者、所有个体或整个制度扩张。制度扩张还可能改变供给、拥挤、互动和资源配置，因此处理版本已经不同。","控制变量不是越多越好。若要总效应A→M→Y，把M固定住会改变所问问题；若控制A与其他原因共同影响的变量，还可能打开原先不存在的关联。需要先说明变量在生成过程中的位置，而不是把相关变量全部加入回归。样本再大也不消除由设计造成的不可区分性。","不能点识别时不必伪装为全知或一无所知。可以保留由假设和材料支持的上下界、方向集合、必要条件排除或具体过程知识，并列明未回答的目标。部分识别必须真的来自相应约束，不能随意给一个区间便称严谨。","原文最后列出一组常见事件偷换：协议文本、核验、执行、日常使用不是一件事；公告、公众理解、到场、口岸处置和全面放行也不能用某一个节点代替整链。每转换一个处理或结果定义，就重新核证其事件、时点、对象和依赖路线。"],"distinctions":[{"leftTitle":"获得机会Z","leftText":"可因随机分配而比较。","rightTitle":"实际接受D","rightText":"受到资格、选择和执行等影响，未必随机。"},{"leftTitle":"局部平均效应","leftText":"指定依从者群体的平均变化。","rightTitle":"全体或个体效应","rightText":"需要另一目标及识别依据，不能从局部平均直接读出。"},{"leftTitle":"未能点识别","leftText":"无法唯一确定目标量。","rightTitle":"毫无信息","rightText":"更强的说法；仍可能有边界、方向或过程约束。"}],"boundaries":["不能把“多数人没有接受机会”理解为随机分配必然失效；应分清机会效应与接受效应。","本讲不提供当前医疗、保险或政策建议。Oregon事实限于官方摘要可核的历史设计，不使用未读全文中的健康数值或个体结论。","多控制一个变量可能改变目标或引入偏差；更多样本只能改进某些估计精度，不自动修复识别。"],"questions":["发现邀请除促成接受外还有直接影响，是否应把邀请随机比较的全部结果撤销？","只分析最终接受者，能自动保持最初随机分组的可比性吗？","为什么“协议存在”不能直接填“日常执行成功”？"],"diagramPath":"/reading-assets/S-2-4/figures/section-2-4-1.png","caseLinks":[{"title":"Oregon 2008年抽签：抽中的是申请机会","href":"https://www.nber.org/papers/w17190"}],"caseNotes":[{"title":"Oregon 2008年抽签：抽中的是申请机会","text":"NBER官方2011年工作论文摘要说明，2008年俄勒冈州一组未参保低收入成年人通过抽签获得申请Medicaid的机会。这个历史设计本身就区分了“抽签获得机会”和“实际参保”；不能把前者改称人人都接受了同一种干预。","sourceLabel":"Finkelstein et al., The Oregon Health Insurance Experiment: Evidence from the First Year","sourceUrl":"https://www.nber.org/papers/w17190","sourceLocator":"Finkelstein等，NBER Working Paper 17190，2011年7月；官方页面摘要前两句（检索返回的官方正文）","boundary":"官方摘要已取得，直接正文/PDF请求当前返回403，未声称读过全文。只用抽签与申请机会的设计事实；不据此认定完整IV条件、个体效果或制度扩张效果。","href":"https://www.nber.org/papers/w17190"}],"sourceRefs":[{"section":"2.4.1","start_line":299,"end_line":306,"startLine":299,"endLine":306}],"outputId":"section-2-4-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["目标定义：令ITT_Y=E[Y|Z=1]−E[Y|Z=0]，这是按机会Z分组的平均差；设计必须说明随机性、结果可比性及失访等条件。","附加条件：若Z随机、确实改变D，且Z仅通过D影响Y、没有反向依从者，并满足一致性与相应无干扰条件，二元情形下可用ITT_Y／(E[D|Z=1]−E[D|Z=0])解释依从者局部平均效果。","限制：排除限制或单调性等条件不成立时，这一局部接受效果解释受损；不能因此自动宣告随机Z的机会效果也不存在。","用途改变：从局部接受效果换到全人群扩张、特定中介操作或个体预测，须补对应假设与材料，不能只换标题。","证据责任：历史Oregon案例在本讲只支持“随机给申请机会并非随机保证参保”这个设计差别；公式是明确假设下的教学说明，不冒作论文的全部识别检验。"],"teachingExamples":[{"title":"教学数学构造：一个比例，两层假设","text":"假设随机给予机会使平均结果增加2单位，使接受比例增加0.25；再假设满足上述二元IV条件。则依从者局部平均效果为2÷0.25=8单位。若机会本身还直接影响Y，分子就含有不经D的路径，8不再有上述解释；在机会随机和测量等条件仍成立时，2仍可表示机会效果。","assumptions":"2和0.25纯为教学设定，完全不是Oregon论文的观测数值；单位和窗口固定。","boundary":"不能用这个算式替现实排除限制或单调性取证，也不能把8赋给每个人。"},{"title":"教学数学构造：控制共同结果会造出关联","text":"令A和U独立且各取0、1，定义S=A+U、Y=U。总体中A不影响Y；若只取S=1的样本，只剩(A,U)=(1,0)与(0,1)，于是A=1者Y=0，A=0者Y=1，出现负关联。控制共同结果S改变了样本结构。","assumptions":"独立、等概率二元变量及确定性函数均为明确构造。","boundary":"这个反例只否定“控制越多必越可靠”；不说明所有控制都坏，也不是现实估计。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学条件反例：发放邀请本身带来额外咨询，即使未接受主干预也影响结果。","effect":"排除限制受损，不能仅用邀请作工具把全部结果差除以接受差；随机邀请的总体效果仍可独立研究。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学条件反例：系统扩张后服务容量不足，而原小规模试验时容量充足。","effect":"处理和共同条件已变，局部试验效果不能未经桥接直接推广到全面扩张。","sourceIds":["theory"]}],"questionAnswers":[{"question":"发现邀请除促成接受外还有直接影响，是否应把邀请随机比较的全部结果撤销？","answer":"不必。先撤去依赖排除限制的“接受效果”解释；若邀请随机性、测量和其他设计条件仍可信，可保留机会效果。","basis":"本节原文及上述公开推导"},{"question":"只分析最终接受者，能自动保持最初随机分组的可比性吗？","answer":"不能。接受是分配后的选择，筛选接受者可能破坏可比性。","basis":"本节原文及上述公开推导"},{"question":"为什么“协议存在”不能直接填“日常执行成功”？","answer":"文本、核验、实施和实际使用是不同事件；后续节点和连接需分别取证。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-4/figures/section-2-4-1.png","alt":"Z：给予机会，例如抽签可申请；D：实际接受，资格／选择／执行；Y：指定结果，对象／单位／窗口；机会效果，比较随机Z；依从者局部效果，另核IV等假设；制度全面扩张效果，供给／拥挤／互动另核。估计目标示意，依据2.4.1；Oregon摘要仅支持申请机会这一设计事实，箭头不是本讲确认的完整机制。","caption":"估计目标示意，依据2.4.1；Oregon摘要仅支持申请机会这一设计事实，箭头不是本讲确认的完整机制。"}],"diagramBrief":"可以切换目标Z、D或整体扩张，显示各自假设与所缺材料；不能把同一数字自动复制到三个目标。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实抽签研究直接体现机会与接受不同；当前只使用官方已取得摘要中的设计事实，形式推导另标教学。"},"openQuestions":["若要复核该研究完整IV设定及各项数值，需要可读的正式论文、补充材料与具体分析位置；本讲不越过已取得摘要的范围。"],"taskId":"S-2-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第293—314行；每节精确范围见sourceRefs","claim_support":["2.4：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-table","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版，印刷页40、49表I、50—52","claim_support":["2.4：9月1日致死病例发病数143、9月7日28；9月8日移除泵柄。","2.4：作者区分发病时点和死亡时点，并说明迁出与移柄前下降。"],"limits":["致死病例不等全部病例；发病时点有估算和未知。","只核相关原作段落与表，不构成净干预效果重估。"],"access_status":"partially_read"},{"id":"oregon-abstract","title":"Finkelstein et al., The Oregon Health Insurance Experiment: Evidence from the First Year","url":"https://www.nber.org/papers/w17190","source_type":"primary","version_or_date":"2011-07，DOI 10.3386/w17190","locator":"NBER Working Paper 17190，官方摘要前两句；检索返回官方正文","claim_support":["2.4.1：2008年Oregon抽签给未参保低收入成年人申请Medicaid的机会。"],"limits":["当前直接网页和PDF打开返回403；仅据官方检索返回摘要，不声称全文已读。","仅支持设计事实，不认证本讲教学公式在该研究中的全部识别条件或具体健康结果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-4/lecture.md","sourcesPath":"/reading-assets/S-2-4/sources.json","sourceSlicePath":"/reading-assets/S-2-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-4/diagrams.md"},"2.4.2":{"title":"2.4.2　局部作用、联合响应与整链","lead":"两段平均作用都是真的，接在一起仍可能没有效果：被前一段改变的人，可能恰好不是会对后一段作出反应的人。关键是同一批对象的联合响应。","explanation":["原文定位：第307—314行；原文锚点 section-2-4-2；短引文：‘两边均值相乘所得1/4不是整链效应’。本题源切片逐字附后，讲解与原文分开。","串联要保存的不只是两个平均数。前段输出是否等于后段输入的实际版本，同一对象和时序能否对应，两段是否有共同支持范围，哪些人同时对两段响应，终端结果是什么，这些共同条件决定链能不能通。不同研究当然可能不兼容；即使来自同一人群，丢掉联合结构也仍会出错。","原文给出一个完整有限反例。s=0和s=1各占一半，处理a和中介m为二元；m(a)=a(1−s)，y(a,m)=sm。s=0者会被处理改变中介，但不响应中介；s=1者响应中介，却不被处理改变中介。两段作用分落在不同的人身上。","因此局部平均A→M为1/2，外部设定M的平均M→Y也为1/2；在实际串联m(a)下，每类人的终端结果始终为0，整链效应为0。平均乘积1/4不等于平均的个体响应乘积0。它是给定函数反驳无条件乘法，不是对任何现实机制的效果估计。","“完整”只能相对于目标、窗口和依赖路线。若目的只是识别一个限定总效应，不必先知道所有微观环节；若要操作中介、跨域搬用或分配责任，就要补上该用途依赖的连接。共享资源、相抵路径和反馈都会改变组合结果，不能把节点分别有证写成同案整链成立。"],"distinctions":[{"leftTitle":"平均边作用","leftText":"每段在人群中分别平均的作用。","rightTitle":"整链作用","rightText":"同一对象沿前后段实际接续的终端差。"},{"leftTitle":"节点各自有证","leftText":"每个局部事实有相应依据。","rightTitle":"联合连接有证","rightText":"版本、身份、时序和共同响应在本案相容。"},{"leftTitle":"完整限定链","leftText":"覆盖当前用途真正依赖的连接。","rightTitle":"穷尽一切机制","rightText":"并不是识别每个限定总效应都要完成的任务。"}],"boundaries":["本反例按原文给定函数精确计算，不能用它声称所有现实中介分析都无效，也不否定另有合格设计识别的总效应。","如果两段响应在每个人身上恒定，或有足够结构条件使所求整链量恰等于均值之积，乘法可能成立；这些是额外条件，不是由两个均值本身推出。","换了处理版本、允许中介操作或终端目标，就要重写计算；数值相同不等于合同相同。"],"questions":["为什么“同一人群”仍不足以保证两段均值可相乘？","本例后段的1/2，是观察实际m(a)得到的结果平均吗？","发现这类组合问题，是否必须撤销独立随机试验的限定总效应？"],"diagramPath":"/reading-assets/S-2-4/figures/section-2-4-2.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.4.2","start_line":307,"end_line":314,"startLine":307,"endLine":314}],"outputId":"section-2-4-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：P(s=0)=P(s=1)=1/2；m(a)=a(1−s)，y(a,m)=sm，取a从0变1。","前段：Δm=m(1)−m(0)=1−s，s=0时为1，s=1时为0，故E[Δm]=1/2。","后段：固定a，外部把m从0设到1，则Δ_my=y(a,1)−y(a,0)=s，平均E[Δ_my]=1/2。","整链：y(a,m(a))=s·a(1−s)=0，因为二元s有s(1−s)=0。故两类中y(1,m(1))−y(0,m(0))均为0，平均仍为0。","错误乘法：E[1−s]E[s]=1/4，但E[(1−s)s]=0；丢掉两段响应之间的对应关系，改变了被计算的量。","结论与责任：这个反例足够否定“两段平均作用总能相乘”的普遍断言；若在别的模型要乘，须另证结构、同质性或适当联合条件，不能据此否定独立合格设计识别的总效应。"],"teachingExamples":[{"title":"原文数学构造：两类响应互不重合","text":"完整两类表：s=0时m(0)=0、m(1)=1、y(a,0)=y(a,1)=0；s=1时m(0)=m(1)=0、y(a,0)=0、y(a,1)=1。每类都在对应串联下得到终端0。两类等权，所以两段边均值各0.5，实际整链均值0。","assumptions":"精确二元域、等权两类、原文给定确定性函数，无随机误差或样本抽取。","boundary":"这是原文形式反例的展开，不是观测研究，不提供现实人群的比例与效应。"}],"counterexamples":[{"identity":"source_counterexample","text":"原文反例中，一个群体只在前段响应，另一个只在后段响应；两边均值都为1/2，整链为0。","effect":"限制无条件的“平均边相乘”；必须保留联合响应，不影响另行识别的总效应。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么“同一人群”仍不足以保证两段均值可相乘？","answer":"同一人群内也可能存在异质响应；必须知道前段与后段响应是否在同一对象上重合。","basis":"本节原文及上述公开推导"},{"question":"本例后段的1/2，是观察实际m(a)得到的结果平均吗？","answer":"不是。它是外部将m从0设为1时的平均响应；在实际串联中s=1者的m并未被a改变。","basis":"本节原文及上述公开推导"},{"question":"发现这类组合问题，是否必须撤销独立随机试验的限定总效应？","answer":"不应。组合推断失败与另一合格设计的总效应是不同依据；按各自依赖逐项保留或降级。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-4/figures/section-2-4-2.png","alt":"s=0，占1/2，a改变m：作用1；同一类：m不改变y，后段作用0；s=0的整链，1×0=0；s=1，占1/2，a不改变m：作用0；同一类：m改变y，后段作用1；s=1的整链，0×1=0。原文数学反例：两边平均各1/2，平均乘积1/4；实际整链平均0。依据2.4.2，非现实数据。","caption":"原文数学反例：两边平均各1/2，平均乘积1/4；实际整链平均0。依据2.4.2，非现实数据。"}],"diagramBrief":"两行必须保持类型身份，不跨行接箭头。可切换是否保留s分层，显示只保留两均值会丢失联合响应；所有数值来自给定函数。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"该节用完整有限反例否定普遍推理，数学构造已直接完成任务；不强配现实案例来伪装经验确认。"},"openQuestions":[],"taskId":"S-2-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第293—314行；每节精确范围见sourceRefs","claim_support":["2.4：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.4.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-table","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版，印刷页40、49表I、50—52","claim_support":["2.4：9月1日致死病例发病数143、9月7日28；9月8日移除泵柄。","2.4：作者区分发病时点和死亡时点，并说明迁出与移柄前下降。"],"limits":["致死病例不等全部病例；发病时点有估算和未知。","只核相关原作段落与表，不构成净干预效果重估。"],"access_status":"partially_read"},{"id":"oregon-abstract","title":"Finkelstein et al., The Oregon Health Insurance Experiment: Evidence from the First Year","url":"https://www.nber.org/papers/w17190","source_type":"primary","version_or_date":"2011-07，DOI 10.3386/w17190","locator":"NBER Working Paper 17190，官方摘要前两句；检索返回官方正文","claim_support":["2.4.1：2008年Oregon抽签给未参保低收入成年人申请Medicaid的机会。"],"limits":["当前直接网页和PDF打开返回403；仅据官方检索返回摘要，不声称全文已读。","仅支持设计事实，不认证本讲教学公式在该研究中的全部识别条件或具体健康结果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-4/lecture.md","sourcesPath":"/reading-assets/S-2-4/sources.json","sourceSlicePath":"/reading-assets/S-2-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-4/diagrams.md"},"2.5":{"title":"2.5　证据契约","lead":"“有来源”只回答材料从哪里来，还没有回答它证明什么。证据是一种针对具体主张的支持关系，需要说明每一步为什么能接上。","explanation":["原文定位：第315—320行；原文锚点 section-2-5；短引文：‘不能因为一种材料有出处，就省略它与当前主张之间的支持关系’。本题源切片逐字附后，讲解与原文分开。","来源是人、档案、仪器或研究；材料是留下的文本、信号或数据；观察记录是按规则整理出的结果；证据是这些记录对某条主张的支持；反例挑战特定主张；判断综合依据与不确定性；行动授权另规定能否据此做什么。不能从最前面的“存在一个可靠机构”一步跳到最后面的“我有权干预”。","按任务记录对象、资料生成过程、研究设计、测量和选择、不确定性、竞争解释及外推边界。材料的用途可能改变其支持关系：一封通知可以直接证明通知文本里写了什么，却不能单独证明公众理解了、现场执行了或结果改善了。正式根实例和前瞻还须按各自合同登记N0、阈值与评价；不该为了形式齐全，给一份普通历史文本伪造G合同。","缺席和沉默没有默认方向。一份日志没有某事件，可能是没发生，也可能是没记录、记录丢失、看不到或不允许披露。只有明确事件本应留下可检出的记录，才有相应的否定信息；反证力随记录和检索能力而变，不因“没搜到”四个字自动很强。","保护性不公开也不是无条件免审。需要说明保护理由、最小范围、期限和可信复核者，并降低不能公开支持的结论强度。若根本无法可信复核，就不得把隐私理由当作强事实主张的通行证；同时也不应为了补一个字段而强迫披露不必要的敏感资料。","冻结后出现反例和残差，保留原记录并按合同降级、暂停或撤回。对象、子型、阈值和成功标准不能事后改写成“其实原来就想问另一个问题”。新的问题可以另建版本；旧失败仍在其原合同中保留。"],"distinctions":[{"leftTitle":"出处可定位","leftText":"能找到材料和版本。","rightTitle":"支持关系明确","rightText":"能说出材料如何支持特定主张、还不能排除什么。"},{"leftTitle":"没有记录","leftText":"在指定材料与检索范围内未找到。","rightTitle":"记录证明没有","rightText":"要求存在足够可靠的应留痕、可检出机制。"},{"leftTitle":"保护性不公开","leftText":"有明确保护依据与限缩、期限、可信复核。","rightTitle":"无需审查的断言","rightText":"没有这种豁免，无法复核时须降级。"}],"boundaries":["Snow记下无法取得信息与受访者报告未饮该水，是不同记录；两者都不能被本讲改写成无误测量的暴露真值。","反例要求针对具体主张：一处数字不一致可影响精确估计，却未必推翻所有独立材料；共同来源或对象边界失效则可能波及更多结论。","没有预先冻结的材料可被诚实地用作探索或历史解释；缺少冻结不能通过伪造时间戳补齐。"],"questions":["某份正式公告能否直接证明所有现场工作人员都按公告执行？","因隐私不能公开个体资料，可以对外保持最高确定性的结论吗？","冻结后出现反例，能否删除原指标改报一个有利指标？"],"diagramPath":"/reading-assets/S-2-5/figures/section-2-5.png","caseLinks":[{"title":"Snow调查中的两种不同“没喝”","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"Snow调查中的两种不同“没喝”","text":"Snow 1855年原作第40页分别记载：六个实例因相关人死亡或离开而无法取得信息；另六个实例有人报告患者病前没有饮用Broad Street泵水。本节只取这一区分：无法得知与得到否定报告是不同材料身份。","sourceLabel":"Snow 1855第二版，p.40","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷页40，段落“With regard to the deaths occurring in the locality belonging to the pump”","boundary":"作者的访谈记录不是全知的暴露测量；这里不把未知补为阴性，也不把报告等同已排除间接饮水。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.5","start_line":315,"end_line":320,"startLine":315,"endLine":320}],"outputId":"section-2-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：材料的生成与可见性决定它能区分哪些可能情形；出处真实不保证测量与目标吻合。","连接：逐项写“这条记录为何支持这条主张，以及仍与哪些替代解释相容”，才能从材料转为有界证据。","反向检验：若同样的缺席能由未发生和未记录两种过程产生，缺席就不足以唯一支持未发生。","结论：按主张登记证据强度、竞争解释与失败；不透明和缺失限制相应结论，不自动消灭所有已有材料。","授权责任：从判断走向行动仍须规范、合法授权、行动上限和停止条件；来源链本身不会生成权限。"],"teachingExamples":[{"title":"教学构造：日志的空白到底排除什么","text":"设一次事件发生时，系统必定生成并保存可检索记录，查询范围也完整；此条件下“无记录”可反对事件发生。若改为记录器只在联网时工作，而目标时段可能断网，则同样空白不能区分未发生与断网未记录。改变的是资料生成条件，不是研究者喜欢哪种答案。","assumptions":"这两套记录系统都是教学设定，未声称现实日志可靠率为100%。","boundary":"实际反证强度需要记录率、保留策略、权限及检索覆盖材料；不能从本构造继承确定性。"}],"counterexamples":[{"identity":"real_counterevidence","text":"历史记录中，Snow把六个无法获取饮水信息的实例与六个报告未饮泵水的实例分别记载。","effect":"“未知”不得并入“否”；但访谈报告本身仍需承认回忆与暴露遗漏限制。","sourceIds":["snow-missing"]},{"identity":"constructed_boundary","text":"教学边界：发现失败后把原先“降低总等待时间”的目标改成“让更多人进入队列”，再声称原方案已成功。","effect":"不同目标需要新版本，不能通过重写成功标准消除原来的失败。","sourceIds":["theory"]}],"questionAnswers":[{"question":"某份正式公告能否直接证明所有现场工作人员都按公告执行？","answer":"不能。公告是文本材料，执行是另外的事件，需要相应记录与连接证据。","basis":"本节原文及上述公开推导"},{"question":"因隐私不能公开个体资料，可以对外保持最高确定性的结论吗？","answer":"不能自动如此。应给保护依据、最小范围、期限和可信复核，并按实际可核程度限制公开结论。","basis":"本节原文及上述公开推导"},{"question":"冻结后出现反例，能否删除原指标改报一个有利指标？","answer":"不能抹去原结果；应保留失败，按合同降级或暂停，新目标另建记录。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-5/figures/section-2-5.png","alt":"来源，谁／仪器／档案；材料与观察记录，生成／整理／选择；证据与反例，针对哪条主张；行动授权，规范／权限／停止；有限判断，支持与未决并存；新反例或残差，保留原失败。概念图，依据2.5；箭头代表论证与程序转换，不表示材料自然升级为授权。","caption":"概念图，依据2.5；箭头代表论证与程序转换，不表示材料自然升级为授权。"}],"diagramBrief":"点击任意转换应显示依据和支持上限。可切换“无记录／明确否定记录／保护性不公开”，保持三种身份，不填造数据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"可定位的一手历史段落直接展示未知与否定报告的区别，适合证据链与缺失问题。"},"openQuestions":[],"taskId":"S-2-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第315—328行；每节精确范围见sourceRefs","claim_support":["2.5：术语、合同、论证责任和原文边界；不据此认证经验事实","2.5.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-missing","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版p.40，饮水调查段","claim_support":["2.5：六例无法取得信息与另六例报告未饮泵水被分别记录。"],"limits":["这是历史访谈记录，不能视为无误的实际暴露分类。"],"access_status":"partially_read"},{"id":"obermeyer-measure","title":"Obermeyer et al., Dissecting racial bias in an algorithm used to manage the health of populations","url":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf","source_type":"primary","version_or_date":"2019-10-25，Science366:447—453","locator":"Science 366 (2019),447—453；pp.447—449 Data and analytic strategy、Health disparities conditional on risk score、Mechanism of bias；PDF1—3页","claim_support":["2.5.1：资料来自某大型学术医院2013—2015年。","2.5.1：算法以医疗费用为预测标签；同分数下两群体次年费用相近而健康负担有群体差异；不由此推断个体或总体预测精度。"],"limits":["已读所用正文及相关图注，未取得个体数据复算。","不把群体比较转成个体诊断，不把费用准确等同健康需要准确，不外推所有模型。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-5/lecture.md","sourcesPath":"/reading-assets/S-2-5/sources.json","sourceSlicePath":"/reading-assets/S-2-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-5/diagrams.md"},"2.5.1":{"title":"2.5.1 测量对象与资料生成","lead":"一个分数可以算得很准确，却没有测到你真正关心的东西。测量先问目标和资料生成，再问误差大小与可比性。","explanation":["原文定位：第321—328行；原文锚点 section-2-5-1；短引文：‘先说明要测什么、材料怎样产生’。本题源切片逐字附后，讲解与原文分开。","原文区分五种对象。直接记录量如按既定协议计得的次数，仍有漏记和事件定义责任；定义性合成指标按规则把若干分量合成，正确计算不证明存在一个由它反映的潜在属性；潜在属性测量要说明观察指标与不可直接见的属性之间的模型、替代解释和验证；形成性条件强调若干条件共同构成或影响目标，不要求它们必然像同一属性的反映项那样同涨同落；预测代理只需对某个未来目标有预测能力，不能因此变成另一个目标的直接测量。","因此，测验分数可以是当前题域表现的可靠记录，却还不是长期能力的完整代表；服务用量下降也可能表示未满足需要；诊断增加可能来自检测更容易，而非疾病真实增加。这些是不同资料生成路径，不能看到一个方向就自动选择最顺耳的故事。","跨群体或时期比较要匹配用途。若估计潜在均值，需要量尺单位和起点有可解释的对应；若逐人按阈值决策，还需个人误差与后果分析。两组使用同一个评分公式，不证明题项含义、作答策略或测量关系相同。共同锚点若漂移，更多样本可能只把同一个不可识别问题估得更精确；应找外部锚定或做敏感性分析。","指标变好至少可能有四类原因：目标真实改善；行为确实适应了狭窄指标却未改善更广目标；入样或报告组成变化；记录被伪造。这些机制可共存，但不能只因指标变化就指控造假。两个合法指标若一个看总量、一个看某分组，也可能方向相反而各自正确。","真实算法案例展示代理错位：费用是被预测的标签，研究比较了同一风险分数下不同群体的费用与健康负担。跨群体费用校准相近，不等于个体预测误差小或总体预测精度都好；用于识别照护需要时，还要验证费用与需要的关系在目标群体中是否相当。反思标签不是宣布所有代理无效；它要求针对当前用途拿出适配证据。"],"distinctions":[{"leftTitle":"预测某标签准确","leftText":"模型对明定目标的预测表现好。","rightTitle":"测到真正关心的属性","rightText":"标签与目标属性、使用目的有经过核对的关系。"},{"leftTitle":"定义性合成指标","leftText":"分量与权重规定分数的构成。","rightTitle":"潜在属性测量","rightText":"需论证观察指标如何反映潜在属性及其可比性。"},{"leftTitle":"形成性条件","leftText":"各条件可能不同方向、共同影响或构成目标。","rightTitle":"反映式指标","rightText":"在模型中是潜在属性的表现，要求不同检验逻辑。"},{"leftTitle":"指标方向相反","leftText":"可能因为对象、分母、权重或任务不同。","rightTitle":"数据必有造假","rightText":"需要独立证据，不能从方向差异直接推定。"}],"boundaries":["Obermeyer研究是特定医院与2013—2015年样本中的算法评估，不能据此评判任何未审查个人或所有现行模型。","观察到群体校准差异不等于已经拆明所有社会机制；更换标签也不自动保证长期健康收益或公平规范已全部满足。","高内部一致性、同一公式或更大样本，均不能独自保证潜在属性测量的构念与跨群体适配。"],"questions":["某测试重测很稳定，能立即断定它测到了长期能力吗？","服务用量下降能否直接证明需要下降？","超时总数增加而超时率下降，是不是必有数据造假？"],"diagramPath":"/reading-assets/S-2-5/figures/section-2-5-1.png","caseLinks":[{"title":"2019年费用预测算法研究：代理与需要不是同一目标","href":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf"}],"caseNotes":[{"title":"2019年费用预测算法研究：代理与需要不是同一目标","text":"Obermeyer等分析一家大型学术医院2013—2015年的资料。被审算法预测医疗费用；论文发现同一风险分数下两群体次年费用相近，却呈现黑人患者更重的健康负担。这是跨群体费用校准较一致，不由此断言总体或个体预测精度很高；这项校准性质也不能替代照护需要的适配检验。","sourceLabel":"Obermeyer et al., Dissecting racial bias in an algorithm used to manage the health of populations","sourceUrl":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf","sourceLocator":"Science 366 (2019), 447—453；印刷pp.447—449，Data and analytic strategy、Health disparities conditional on risk score、Mechanism of bias；PDF第1—3页","boundary":"按论文的特定样本、指标和用途理解；本讲未复算个体数据，不作个人医疗判断，也不声称修正标签后真实长期结果已改善。","href":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf"}],"sourceRefs":[{"section":"2.5.1","start_line":321,"end_line":328,"startLine":321,"endLine":328}],"outputId":"section-2-5-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：观察分数由目标属性、测量规则、接触机会、选择和记录过程共同生成；不同生成过程可给同一分数。","分类：先登记测的是直接量、定义合成、潜在属性、形成性条件还是预测代理，明确哪种错误会影响当前用途。","连接：一个指标对标签预测准确，只能直接支持该标签任务；换成需要、能力或价值判断时，须另证测量与用途的桥接。","比较条件：当群体或时间改变，核对单位、起点、锚点、个人误差与样本构成；不能由同一公式推出相同心理过程。","结论：报告指标变化时同时保留竞争生成机制，提出可区分的检查；没有足够材料时不把一种解释升为事实。"],"teachingExamples":[{"title":"教学数学构造：均值变化还是量尺起点漂移","text":"假设观测分数S=θ+b，θ是待测属性，b是量尺起点。两期观测均值由4升到6，既可能是θ增加2且b不变，也可能θ不变而b增加2；只观察S无法区分。即使每期样本无限多、观测均值无误，仍须外部锚定或可检验约束才能解释变化。","assumptions":"加法测量模型、同单位、没有其他误差，仅为展示可识别性。","boundary":"不是任何量表或人群的实测事实；具体测量关系可能非线性，需另建模型。"},{"title":"教学构造：两个正确指标可以反向","text":"某服务在第一期处理10件，其中2件超时；第二期处理30件，其中3件超时。超时总数由2增至3，而超时率由20%降为10%。两者都算对，回答的分别是总负担和个案比例，不能仅凭相反方向认定一方造假。","assumptions":"件数为教学设定，事件定义与窗口可比；没有抽样或漏报。","boundary":"不代表真实服务改善已被证明；第二期案件难度、需求和未处理者仍可能改变评价。"}],"counterexamples":[{"identity":"real_counterevidence","text":"研究显示，同一风险分数下两群体次年费用相近，即跨群体费用校准较一致，但黑人患者的健康负担更重。","effect":"这限制“跨群体费用校准一致就能公平识别健康需要”的推理；它不证明个体费用预测精度很高，也不否定费用预测任务本身。","sourceIds":["obermeyer-measure"]},{"identity":"constructed_boundary","text":"教学构造中量尺起点漂移与真实属性变化产生同样的观测均值变化。","effect":"更多同型观察不能独自识别两种机制，应增加锚定或明确敏感性。","sourceIds":["theory"]}],"questionAnswers":[{"question":"某测试重测很稳定，能立即断定它测到了长期能力吗？","answer":"不能。稳定性是一种性质，构念内容、题域外推广、测量关系和用途适配还须论证。","basis":"本节原文及上述公开推导"},{"question":"服务用量下降能否直接证明需要下降？","answer":"不能。可及性、价格、供给、入样与记录变化都可能改变用量，须有区分材料。","basis":"本节原文及上述公开推导"},{"question":"超时总数增加而超时率下降，是不是必有数据造假？","answer":"不是。分母增加即可产生这种情况；先核对象、分母、窗口和算法，再调查具体异常。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-5/figures/section-2-5-1.png","alt":"资料生成，服务可及性／记录；观测标签：费用，假设预测此标签准确；费用任务的评价，只回答费用预测；真正关心的目标，照护需要；需要与费用的桥接，群体／时间／误差；面向需要的使用评价，另取证，不能跳过。概念图依据2.5.1；费用与需要的错位参见Obermeyer等2019 pp.447—449。无虚构个体值或效果曲线。","caption":"概念图依据2.5.1；费用与需要的错位参见Obermeyer等2019 pp.447—449。无虚构个体值或效果曲线。"}],"diagramBrief":"上路检查标签预测，下路检查目标用途。交互切换评价标签“费用／健康负担”时，应更换对应证据和指标，不能只改坐标名称。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手论文直接研究预测标签与健康需要的错位，适合本节的测量对象和代理用途区分。"},"openQuestions":["若要把该结论移到另一机构或现行算法，需要该版本的标签、资料生成、群体可比性及真实结局资料。"],"taskId":"S-2-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第315—328行；每节精确范围见sourceRefs","claim_support":["2.5：术语、合同、论证责任和原文边界；不据此认证经验事实","2.5.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-missing","title":"John Snow, On the Mode of Communication of Cholera","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"1855年第2版p.40，饮水调查段","claim_support":["2.5：六例无法取得信息与另六例报告未饮泵水被分别记录。"],"limits":["这是历史访谈记录，不能视为无误的实际暴露分类。"],"access_status":"partially_read"},{"id":"obermeyer-measure","title":"Obermeyer et al., Dissecting racial bias in an algorithm used to manage the health of populations","url":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf","source_type":"primary","version_or_date":"2019-10-25，Science366:447—453","locator":"Science 366 (2019),447—453；pp.447—449 Data and analytic strategy、Health disparities conditional on risk score、Mechanism of bias；PDF1—3页","claim_support":["2.5.1：资料来自某大型学术医院2013—2015年。","2.5.1：算法以医疗费用为预测标签；同分数下两群体次年费用相近而健康负担有群体差异；不由此推断个体或总体预测精度。"],"limits":["已读所用正文及相关图注，未取得个体数据复算。","不把群体比较转成个体诊断，不把费用准确等同健康需要准确，不外推所有模型。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-5/lecture.md","sourcesPath":"/reading-assets/S-2-5/sources.json","sourceSlicePath":"/reading-assets/S-2-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-5/diagrams.md"},"2.6":{"title":"2.6　类比契约","lead":"“这像另一件事”最有用的地方，是提醒我们下一步该查什么；它不能把另一件事的原因、评价和解决办法直接搬过来。","explanation":["原文定位：第329—334行；原文锚点 section-2-6；短引文：‘类比只是一种问题生成工具’。本题源切片逐字附后，讲解与原文分开。","一份合格类比至少列出源域、目标域、共享结构、关键差异、不可迁移条件、变量映射和区分性检验，并在正文明确称为类比。例如把排队比作蓄水，可能共享“输入、存量、输出”的结构；但人会离队、改变选择或策略回应，水量与人数也不能未经单位和过程说明混算。","变量映射使“像”从修辞变成可检查提案：源域的哪个量对应目标域的哪个量，关系在何种操作下仍成立，何时会失效。相似图形、相同词语、好听故事和相似结果都不足以完成这份映射。把“组织免疫”“社会温度”当作已测机制，正是应避免的越界。","类比能提出检查清单：源域有哪些通道、边界或竞争解释在目标域也值得调查？但源域经验因果关系并不自动成为目标域的事实。还要在目标域检验对应操作、测量和替代解释；正式G-instance要求也不能由类比取代。","反向条件要能实际限制主张。若研究者无论看到什么都说“这仍然很像”，类比就无法筛除错误候选。合理写法是：若目标域出现某种行为、对象身份或资源约束，映射不再适用；若区分性检验尚未完成，只保留启发性候选。规范评价和行动方案尤其不能靠相似直接迁移。"],"distinctions":[{"leftTitle":"结构相似","leftText":"部分关系或指标可对应。","rightTitle":"机制相同","rightText":"因果过程和作用条件相同，需新的区分性证据。"},{"leftTitle":"启发问题","leftText":"决定先查什么。","rightTitle":"确认答案","rightText":"材料已能支持哪种关系，效力不同。"},{"leftTitle":"类比中的评价","leftText":"源域按其价值标准得到的判断。","rightTitle":"目标域的正当性","rightText":"必须重新公开目标、权利、风险与授权。"}],"boundaries":["现实研究中相似统计量可来自不同形成过程；不能只因两个数接近就指定相同社会制度。","类比有用不要求每一点相同，但它声称迁移的那部分必须明确，差异一旦触及关键前提就要停用或缩小。","本讲不把生物类比用于给现实个人或群体指定地位、人格或治理方案。"],"questions":["两个系统都画出中心辐射图，能否直接断定中心节点控制全部资源？","把人的行为比作水流，最先应补什么？","一个类比已有反向材料，但仍能启发某个问题，必须全部丢弃吗？"],"diagramPath":"/reading-assets/S-2-6/figures/section-2-6.png","caseLinks":[{"title":"2022年古DNA研究对“像类人猿”的明确限缩","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"caseNotes":[{"title":"2022年古DNA研究对“像类人猿”的明确限缩","text":"Skov等研究尼安德特人社区时比较了遗传多样性模式，却在“Inferring social organization”明确提醒：相似的Y染色体与线粒体共祖时间比值，不必然给出相同社会组织，多种情景可以产生相似统计量。","sourceLabel":"Skov et al., Genetic insights into the social organization of Neanderthals","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","sourceLocator":"Nature610 (2022),519—525；PMC正文Inferring social organization，比较47个人群及10种类人猿亚种后的谨慎说明段（本讲不使用其具体比较数值）","boundary":"这里只用作者对类比的限制，不根据古DNA给出现代群体评价，也不复算其人口史模型。","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"sourceRefs":[{"section":"2.6","start_line":329,"end_line":334,"startLine":329,"endLine":334}],"outputId":"section-2-6","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：源域已知关系依赖其具体对象、变量和操作条件；相似性只覆盖其中某些方面。","连接：先写映射与差异，才能判断哪些源域问题可作为目标域候选，以及什么观察会否定映射。","结论：类比授权的是提问题与生成待检关系，不是直接宣告目标域机制、价值判断或行动已成立。","证据责任：目标域支持必须来自自身材料及桥接；即使源域研究很可靠，也不能替目标域补出未观察条件。","失败责任：保留不相似处和反向材料；不能将映射失败解释成目标域“异常”而永不修正类比。"],"teachingExamples":[{"title":"教学类比：排队像蓄水，何时不再像","text":"源域是水箱，目标域是服务队列；把流入映射为新到人数，把水位对应为队列长度，把流出对应为服务完成，可生成“到达大于处理能力时存量会积累”的待查问题。但若人可中途离队、重复排号或见队长便不来，实际队列还需额外通道。应记录到达、完成、退出和重复计数，检验哪种守恒式适用，而非直接把水箱参数代给人群。","assumptions":"这是明确标记的教学类比，未观测任何现实队列；单位和事件规则由目标域重新声明。","boundary":"类比不证明服务效果，更不证明人应像水一样被控制；目标域的经验与规范条件另核。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Skov等2022年研究明确提醒，尼安德特人与类人猿相近的Y染色体／线粒体共祖时间比值，不必然意味着相同社会组织；多种情景可产生相似比值。","effect":"一个真实研究自身就区分统计相似与社会解释，不能用相似指标跳过生成机制。","sourceIds":["skov-analogy"]}],"questionAnswers":[{"question":"两个系统都画出中心辐射图，能否直接断定中心节点控制全部资源？","answer":"不能。图形相似不告诉我们边的语义、实际流动、权限或替代通道；须核目标域材料。","basis":"本节原文及上述公开推导"},{"question":"把人的行为比作水流，最先应补什么？","answer":"明确变量和单位映射、人的退出与策略反应等关键差异、不可迁移条件，以及能够区分这些过程的目标域记录。","basis":"本节原文及上述公开推导"},{"question":"一个类比已有反向材料，但仍能启发某个问题，必须全部丢弃吗？","answer":"不一定。限制或撤去失效部分，保留明确仍适用的启发；不能保留原来的强机制结论。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-6/figures/section-2-6.png","alt":"源域，已有关系及条件；显式映射，共享结构＋关键差异；目标域候选问题，仍待检验；源域因果／规范结论，不能直接迁移；不可迁移条件，反向信号／失败方式；目标域独立材料，检验操作与替代解释。概念图，依据2.6；古DNA例中的谨慎解释见Skov等2022。无数据曲线或自动迁移结论。","caption":"概念图，依据2.6；古DNA例中的谨慎解释见Skov等2022。无数据曲线或自动迁移结论。"}],"diagramBrief":"交互可打开某项关键差异，显示它阻断哪条映射；不提供“相似度高所以可行动”的自动按钮。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手研究直接公开相似指标不能替代社会机制的限制，正好展示类比的适用上限。"},"openQuestions":[],"taskId":"S-2-6","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第329—340行；每节精确范围见sourceRefs","claim_support":["2.6：术语、合同、论证责任和原文边界；不据此认证经验事实","2.6.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"skov-analogy","title":"Skov et al., Genetic insights into the social organization of Neanderthals","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","source_type":"primary","version_or_date":"2022-10-19，DOI10.1038/s41586-022-05283-y","locator":"Nature610:519—525；Inferring social organization中讨论Y／mtDNA共祖时间比值与多种情景的段落","claim_support":["2.6：作者明确提醒相似遗传比值不必然代表相同社会组织，形成过程有多种可能。"],"limits":["已读本讲所用正文；未复算基因数据和补充模型。","仅用于说明类比的支持上限。"],"access_status":"partially_read"},{"id":"skov-kinship","title":"Skov et al. 2022，亲缘分析（同一研究）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","source_type":"primary","version_or_date":"2022-10-19，同一论文不同支持位置","locator":"Genetic relationships，Chagyrskaya D/H段；Table1","claim_support":["2.6.1：原作以一级亲缘和不同线粒体基因组判断D与H为父女。"],"limits":["与skov-analogy是同一论文，不计两项独立研究。","亲缘不自动推出统治身份；这项用途限制为本讲分析，不冒作原作者的制度结论。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-6/lecture.md","sourcesPath":"/reading-assets/S-2-6/sources.json","sourceSlicePath":"/reading-assets/S-2-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-6/diagrams.md"},"2.6.1":{"title":"2.6.1 类比 形式实例与受检比较","lead":"“像”“在模型中是同一类”“目标世界中有证”是三种身份。把它们分开，既不贬低类比，也不让类比借到它尚未获得的证明力。","explanation":["原文定位：第335—340行；原文锚点 section-2-6-1；短引文：‘启发性类比、满足明确数学前提的形式实例、经过独立材料检验的目标域关系，是三种不同状态’。本题源切片逐字附后，讲解与原文分开。","第一种是启发性类比：说明相似与差异，给出值得检验的关系。第二种是形式实例：变量和操作满足一个数学命题的全部前提，结论在该模型中由证明得到，不依靠故事像不像。第三种是受检的目标域关系：独立材料连同桥接支持具体关系，其支持来自材料，不来自“像”这个词。三种可以在一项研究中配合，但不能自动升级。","例如抽象图中的“存在路径”是形式性质；现实中把一个链接映射为可以发送信息，需要核对应渠道确实可用；声称信息实际传过去并改变结果，又要另外的事件和效果证据。即使图同构，边代表合作、供电或亲缘时，现实操作含义也完全不同。","历史与考古材料更需要分层：痕迹怎样物理形成，是一层；它对应什么活动功能，是另一层；参与者处于何种社会关系和制度，是第三层。工具痕迹相似可以提出活动问题，不自动指认同一种权力制度；亲缘鉴定可以支持血缘关系，不单独给出谁统治谁。年代更准确有助于排序，也不独自回答事件意义。","尊重不同知识来源，不等于把它们对所有问题赋同样权重。年代测量、遗传关系、地方知识、口述与文本语境可能各自回答不可互换的问题。一个材料不适合回答某命题，并不等于它对所有问题都无效；反之，不能因为一种知识很重要，就让它免于该用途所需的批评。","本节续用古DNA研究，但新增观察点是“关系识别的支持范围”：亲缘结论依赖遗传材料和解释，而有关统治或规范地位的结论另需社会证据。这个限制是本讲对该材料用途的分析，不是把研究作者没有提出的政治结论硬塞给他们再反驳。"],"distinctions":[{"leftTitle":"形式实例","leftText":"对象与映射满足明定数学前提。","rightTitle":"现实实例有证","rightText":"目标域的映射与前提有相应观测和设计支持。"},{"leftTitle":"遗传亲缘","leftText":"生物亲缘关系的证据判断。","rightTitle":"社会权力","rightText":"角色、规则、支配、资源与制度关系；不能从亲缘自动推出。"},{"leftTitle":"相似痕迹","leftText":"可能的形成过程线索。","rightTitle":"相同制度","rightText":"需要活动与社会关系的追加依据。"}],"boundaries":["古DNA研究的父女关系结论不单独证明男性统治、继承规则或全部社区制度；本讲不声称这些制度一定不存在，只是此材料不足以决定。","形式同构保持的是登记的结构性质，不是所有日常语义和因果参数。更准确的年代也不自动恢复事件全部意义。","比较研究不是一律只能启发；经过独立目标域材料检验后，可按实际设计承担有限论证职责。"],"questions":["两个组织图完全同构，是否足以证明两组织实际决策机制相同？","确定一对古人是父女，能否直接写成“父亲统治社区”？","类比获得目标域独立材料后，支持来自类比本身吗？"],"diagramPath":"/reading-assets/S-2-6/figures/section-2-6-1.png","caseLinks":[{"title":"Chagyrskaya的父女关系：材料支持哪一种关系","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"caseNotes":[{"title":"Chagyrskaya的父女关系：材料支持哪一种关系","text":"Skov等2022年论文在“Genetic relationships”中结合一级亲缘与不同线粒体基因组，判断Chagyrskaya H是D的女儿。本讲据此区分：这是一项有遗传材料支撑的亲缘判断，不能仅凭这层关系就补写统治身份或制度。","sourceLabel":"Skov et al. 2022，亲缘分析正文","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","sourceLocator":"Nature610 (2022),519—525；PMC正文Genetic relationships中“One adult male individual, Chagyrskaya D”段及Table1","boundary":"“亲缘不自动给出统治”是本讲的用途限制；不声称论文作者提出或否定了某种统治制度，也不据该地点推广全部尼安德特人社会。","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"sourceRefs":[{"section":"2.6.1","start_line":335,"end_line":340,"startLine":335,"endLine":340}],"outputId":"section-2-6-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["分类前提：分别明确是相似性提案、数学前提实例，还是有目标域材料的经验比较。","形式连接：若声明了图同构或命题实例，逐项验证映射保持的对象、关系和操作；只有被保持的性质可随证明转移。","经验连接：现实关系需要材料生成、操作、时间、身份及替代解释的检验；形式同构不直接证明实际使用或因果效果。","历史连接：从痕迹到功能，再到社会关系，每一步列新增假设和区分材料；任何一层缺失都不能用其他层“补真”。","结论：经检验的比较可以进入论证，但应精确标注支持来自哪里，并保留未被检验的关系。"],"teachingExamples":[{"title":"教学数学构造：同构图可以传递可达性，不能传递权力","text":"令G₁的节点为{a,b,c}、边为{a→b,b→c}；G₂节点为{1,2,3}、边为{1→2,2→3}。映射a↦1、b↦2、c↦3逐边保持，所以G₁存在a到c的路径时，G₂存在1到3的路径。若将一图解释为授权链、另一图解释为同事联系，图同构并不把授权语义一起证明出来。","assumptions":"两个图和全部边为教学给定；“授权链／同事联系”只是两种假设语义。","boundary":"证明仅覆盖图中可达性，不能证明现实关系真存在、信息实际传递或谁有权行动。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：两个墓葬的工具磨损很像，研究者直接断定两地具有相同统治制度。","effect":"至少跳过痕迹形成、活动功能与社会关系的多步桥接；应退回候选并查相应材料。","sourceIds":["theory"]},{"identity":"unresolved_boundary","text":"亲缘证据能够支持父女关系，但单独不能区分多种可能的社会权力安排。","effect":"对权力关系保持未决，而非撤销有据的亲缘结果。","sourceIds":["skov-kinship"]}],"questionAnswers":[{"question":"两个组织图完全同构，是否足以证明两组织实际决策机制相同？","answer":"不足。同构只保持图中已定义的关系结构；实际边的语义、流程、资源、操作及结果需另核。","basis":"本节原文及上述公开推导"},{"question":"确定一对古人是父女，能否直接写成“父亲统治社区”？","answer":"不能。亲缘和统治是不同关系，后者需要社会与制度证据；不确定统治关系也不取消亲缘证据。","basis":"本节原文及上述公开推导"},{"question":"类比获得目标域独立材料后，支持来自类比本身吗？","answer":"来自那些材料、设计与桥接。应更新材料身份和结论范围，而不是把“像”当成新增证据。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-6/figures/section-2-6-1.png","alt":"启发性类比，相似＋差异；形式实例，完整前提＋映射；受检目标域关系，独立材料＋桥接；痕迹怎样形成，物理过程；对应什么活动，功能解释；何种社会关系，制度／权力另取证。上排是三种材料与论证身份，非升级流水线；下排是考古解释的分层。依据2.6.1及Skov等2022有限亲缘例。","caption":"上排是三种材料与论证身份，非升级流水线；下排是考古解释的分层。依据2.6.1及Skov等2022有限亲缘例。"}],"diagramBrief":"不在上排画自动升级箭头。下排每跨一层可展开支持材料与竞争解释，缺材料时停在已支持层，不将其余层填成事实。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"该真实研究可清楚展示材料支持的关系种类与社会解释的额外责任；与上一节复用同案但不重复类比叙事。"},"openQuestions":["统治、权利与制度等问题需要另有活动、资源与社会关系材料；本讲没有取得可决定这些问题的证据。"],"taskId":"S-2-6","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第329—340行；每节精确范围见sourceRefs","claim_support":["2.6：术语、合同、论证责任和原文边界；不据此认证经验事实","2.6.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"skov-analogy","title":"Skov et al., Genetic insights into the social organization of Neanderthals","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","source_type":"primary","version_or_date":"2022-10-19，DOI10.1038/s41586-022-05283-y","locator":"Nature610:519—525；Inferring social organization中讨论Y／mtDNA共祖时间比值与多种情景的段落","claim_support":["2.6：作者明确提醒相似遗传比值不必然代表相同社会组织，形成过程有多种可能。"],"limits":["已读本讲所用正文；未复算基因数据和补充模型。","仅用于说明类比的支持上限。"],"access_status":"partially_read"},{"id":"skov-kinship","title":"Skov et al. 2022，亲缘分析（同一研究）","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","source_type":"primary","version_or_date":"2022-10-19，同一论文不同支持位置","locator":"Genetic relationships，Chagyrskaya D/H段；Table1","claim_support":["2.6.1：原作以一级亲缘和不同线粒体基因组判断D与H为父女。"],"limits":["与skov-analogy是同一论文，不计两项独立研究。","亲缘不自动推出统治身份；这项用途限制为本讲分析，不冒作原作者的制度结论。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-6/lecture.md","sourcesPath":"/reading-assets/S-2-6/sources.json","sourceSlicePath":"/reading-assets/S-2-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-6/diagrams.md"},"2.7":{"title":"2.7　来源契约","lead":"来源表不是越长越好，而是每一个判断都能回到恰好支持它的位置。引用理论说明怎样检验，不等于已经拿到检验的现实结果。","explanation":["原文定位：第341—348行；原文锚点 section-2-7；短引文：‘方法定义不等于经验支持’。本题源切片逐字附后，讲解与原文分开。","每项来源要写领域、案例类型、时间与地区、支持范围和外推边界，并登记相关反例。原始材料、二手解释、本框架推断分栏，使读者既能从一句判断找到原位置，也能从一份材料看见它究竟被用来支持哪些有限主张。双向链接的目的在于检查推断是否越界，不是给出处贴权威标签。","“概念定义”“字段映射”“方法说明”决定要问什么、如何记录和在哪里停止；它们不能进入empirical_evidence_records充当对象事实或机制支持。比如本书定义G2怎样检验指定通道，并不证明某个现实对象的这条通道已存在。本书讲C怎样组合结果，也不等于所有被组合环节已经有实际材料。","申请正式经验支持时，需要独立登记的实例资料：对象与尺度、时间窗、研究设计、N0、结果、不确定性、复核或复现及证据等级。这里承接2.1两阶段准入，不是把每份档案都强行改成现代实验；普通领域证据按原设计保留，正式G支持则按对应合同取得。","C有结果登记、机制条件和规范桥接等不同用途，不能把它统一当作额外因果事实。CM现实机制判断仍需相应实例证据。所谓问题目录、结果合同和框架自身说明，最多给检验责任，不会通过被重复引用来填补外部资料缺口。","来源越接近原始生成处，通常越有利于核对具体细节，但原始材料也会错误、遗漏或带有解释。应分别看版本、生成过程、实际位置与主张对应，而不是将“一手”理解为不可批评。下一节专门处理来源关系与阅读范围，再下一节处理独立性和错误怎样传播。"],"distinctions":[{"leftTitle":"方法来源","leftText":"给出术语、设计或记录规则。","rightTitle":"经验来源","rightText":"提供对象、观察或实例结果，需判断支持范围。"},{"leftTitle":"一手记录","leftText":"接近实际形成过程，可核具体位置。","rightTitle":"无条件真相","rightText":"不存在此种来源特权，原记录仍有局限。"},{"leftTitle":"来源支持","leftText":"恰好支持某条限定主张。","rightTitle":"权威背书","rightText":"借名望跨过支持关系，不能替代证据。"}],"boundaries":["原文和技能均不能独立认证其对现实世界的经验断言；本讲引用理论只解释作者说了什么以及其条件。","文献数量多、书目信息齐全，只让回查更容易，不替代主张与事实之间的支持关系。","已有历史证据不必因未转为G-instance而丢弃，但也不能凭历史地位自动取得正式G资格。"],"questions":["引用本书G2定义，能否算作“指定通道已经被实证支持”的一条证据？","一篇一手论文中的作者推测，能否按“原始事实”登记？","当前主张从“某措施被宣布”变成“某措施实际改变结果”，原来的公告来源够吗？"],"diagramPath":"/reading-assets/S-2-7/figures/section-2-7.png","caseLinks":[{"title":"同一原作，不同句子的支持范围不同","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"同一原作，不同句子的支持范围不同","text":"Snow 1855年原作第40页支持其关于9月7日会面、次日移除泵柄的记述；第51—52页又限制了把停用后下降直接归因于行动的解释。本节只把这些位置分别连到“事件日期”和“因果归因的限制”。","sourceLabel":"Snow 1855第二版，对应事件与限制段","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷p.40及pp.51—52","boundary":"日期记录不是净效果证据；原作中“我获知／我判断”也需保留其作者叙述身份，不与后世独立确认合并。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.7","start_line":341,"end_line":348,"startLine":341,"endLine":348}],"outputId":"section-2-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：一个文献可以包含定义、事实、作者解释和未决推测，不同段落的支持对象不同。","连接：逐主张登记来源位置与支持上限，分开原材料、他人解释和本讲推断，才能检查借用是否恰当。","排除：仅有方法合同并没有实例结果，因此不能把该合同塞进经验记录来支持机制存在。","结论：正式G／CM相关强主张须有对应外部实例资料；已有领域材料按其实际设计保留，不能被编号或引文数量升级。","复核责任：若主张变了，重新检查支持关系；同一文献可支持某个日期事实，却不支持以该日期为起点的净因果叙事。"],"teachingExamples":[{"title":"教学构造：同一本手册有两种可用内容","text":"假设手册第一章定义“合格读数”为误差不超过e，附录记录某次实测误差。定义段可支持术语含义，不能支持那次实测合格；附录数据若测量和计算可信，才可能支持该实例判断。若附录只是演算示例，它仍不能变成现实测量。","assumptions":"手册、阈值与实测均是教学设定，未指称真实出版物。","boundary":"例子说明来源角色，不认证任何实际设备或实例。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Snow记述了9月7日面谈及次日拆柄，也在后文保留停用前已下降的限制。","effect":"同一来源支持事件日期，不能据日期存在就跳到拆柄导致全部下降。","sourceIds":["snow-use"]}],"questionAnswers":[{"question":"引用本书G2定义，能否算作“指定通道已经被实证支持”的一条证据？","answer":"不能。定义说明检验任务和要求，不提供目标对象的实例资料。","basis":"本节原文及上述公开推导"},{"question":"一篇一手论文中的作者推测，能否按“原始事实”登记？","answer":"不能。要区分记录、分析与推测，并标出原文表达的不确定性。","basis":"本节原文及上述公开推导"},{"question":"当前主张从“某措施被宣布”变成“某措施实际改变结果”，原来的公告来源够吗？","answer":"不够。主张的事件与因果目标改变了，必须另核执行、结果和反事实比较。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-7/figures/section-2-7.png","alt":"原始材料，版本／时间／位置；材料实际内容，记录与作者解释分开；本讲有限判断，支持范围／反例；框架定义和方法，决定问什么、怎样查；外部实例证据，对象／设计／结果；正式经验支持申请，核相应合同。来源关系图，依据2.7；方法定义未画成通往经验支持的证据箭头。","caption":"来源关系图，依据2.7；方法定义未画成通往经验支持的证据箭头。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。双向查阅：选判断显示材料位置；选材料显示其被用于哪些主张。方法来源和经验记录保持不同标签，不按文献数量累加分值。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一原作的两处材料能支持不同范围的判断，直接展示逐主张来源登记。"},"openQuestions":[],"taskId":"S-2-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第341—362行；每节精确范围见sourceRefs","claim_support":["2.7：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-use","title":"John Snow 1855，事件与因果限制","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"p.40；pp.51—52","claim_support":["2.7：面谈与拆柄日期记述；停用前已下降的限制。"],"limits":["日期事实不直接支持净效果。"],"access_status":"partially_read"},{"id":"snow-version","title":"John Snow作品及Gutenberg数字版书目信息","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855第二版；Gutenberg release 2024-02-07","locator":"页面首部Release date；书名页第二版和London1855","claim_support":["2.7.1：历史作品1855第二版与数字发布2024为同一作品不同载体。"],"limits":["未作数字转录与印本逐字校勘；载体不构成独立调查。"],"access_status":"partially_read"},{"id":"snow-trace","title":"John Snow 1855，Table I及说明","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"pp.49—51，Table I日期行、Date unknown行和总计；表后逐日下降描述","claim_support":["2.7.2：43个已知日期行加总571，未知日期45，总计616（加总为本讲派生）。","2.7.2：9月6日20、9月7日28，限制严格逐日单调的读法。"],"limits":["原表为最终致死病例发病日与死亡日两列；本讲只算前者。","与snow-use、snow-version为同一作品不同位置，不增加独立研究数；异常不揭示成因。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-7/lecture.md","sourcesPath":"/reading-assets/S-2-7/sources.json","sourceSlicePath":"/reading-assets/S-2-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-7/diagrams.md"},"2.7.1":{"title":"2.7.1 来源的关系与实际使用范围","lead":"来源有家谱，阅读也有范围。一个文件被转录、转载或改版后，不会因为网址变多就自动增加独立证据。","explanation":["原文定位：第349—356行；原文锚点 section-2-7-1；短引文：‘找到链接、完成下载和理解论证也不是同一动作’。本题源切片逐字附后，讲解与原文分开。","应分别记录只见目录、读摘要、读相关章节还是读全文。找到链接证明发现一个入口，下载证明获得文件，理解某段论证还需要实际检查其前提和材料。只读相关段可以诚实支持这些段落里的有限事实，不可把阅读范围放大成全文复核。","同一数据的不同分析、预印本与正式版、原报告与机构转述，都要保留关系。另一个算法可能发现原分析的错误，但没有自动生成新观察；正式版也可能改变样本、结局或口径，须先列变化再比较，不能只见标题近似就合并或当复现。","对理论历史也要区分：实际采用、仅被提及、明确限制或拒绝、与当前文本相容、分析者现在提出新连接。这几种历史命题各自需要记录。“今天看来相容”不证明作者当年受它影响；没有找到采用证据，也不足以写“作者从未考虑”。","档案缺席经过多道筛选：事件是否生成记录、是否保存或销毁、是否开放、检索能否找到、最后是否被叙述者选入。只有知道某类事件本应留下且能够被发现的痕迹，缺席才有相应反证力。一次研究窗口拿不到文件，不代表其他研究者或整个项目都没有它。","口述中的日期错误仍应更正，但叙述方式可能提供记忆、经验和意义的材料。不能因一处年表不准就宣告全部口述无价值，也不能以口述有价值为由拒绝纠正其事实错位。不同用途分别评价。"],"distinctions":[{"leftTitle":"全文存在","leftText":"可有机会取得完整文本。","rightTitle":"本次已读全文","rightText":"实际进入并检查全部文本；不能由存在或下载代替。"},{"leftTitle":"同源多版","leftText":"可能有有价值的修订与重分析。","rightTitle":"独立复现","rightText":"需要说明独立观察或设计，不由版本数量决定。"},{"leftTitle":"当前未查到","leftText":"当前搜索窗口的材料状态。","rightTitle":"历史从未存在","rightText":"对所有相关时空作更强断言，证据责任远高。"},{"leftTitle":"事实日期准确","leftText":"用于事件排序和事实核对。","rightTitle":"记忆表达有意义","rightText":"用于理解叙述与经验；两种评价可同时进行。"}],"boundaries":["本题Snow案例只以其1855原作相关段落的数字转录为依据，未把数字转录当作另一次历史调查。","未亲读原始登记簿就不声称核过登记簿；原作声称查询过登记簿，是关于作者调查过程的记述。","新解释可以有价值，但应登记为今天的分析连接，不能伪装成历史采用关系。"],"questions":["看到一份论文正式版与预印本，最先该比较什么？","只读了相关两节，能否在来源里写“已阅读全文”？","口述中一个日期错误，应如何处理其余内容？"],"diagramPath":"/reading-assets/S-2-7/figures/section-2-7-1.png","caseLinks":[{"title":"1855年文本与数字版：一份历史作品的两种载体","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"1855年文本与数字版：一份历史作品的两种载体","text":"本讲使用的Gutenberg页面明确保留Snow作品1855年第二版的书名与出版信息，数字发布信息则列2024年。数字文本让原段可检索，并不是2024年重新进行了一次Broad Street调查。","sourceLabel":"Snow作品的Gutenberg数字转录版","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"Gutenberg页首Release date与书名页“SECOND EDITION, MUCH ENLARGED”“LONDON…1855”；本讲所用历史段pp.39—52","boundary":"只核书目信息及所引段落；未声称全文逐字校勘印本。数字转录和1855作品不计两份独立经验来源。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.7.1","start_line":349,"end_line":356,"startLine":349,"endLine":356}],"outputId":"section-2-7-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：来源文件数、底层资料数和阅读范围是三种计量对象。","连接：建立来源关系后，才能区分新增资料、重分析、转录、版本变化和重复转述；阅读身份决定当前能够亲自核实到哪里。","历史推论：把“没找到”提升为“从未发生”，需要额外证明应留痕和可检索条件；否则只报告当前范围内未获材料。","结论：按实际读到的范围引用，按实际新增的信息评价来源，不以文件、引用或网址数量替代独立性。","责任：对日期、数字等可纠正内容负责，同时保留不同材料对不同问题的独特贡献。"],"teachingExamples":[{"title":"教学构造：口述日期错了，哪些结论受影响","text":"设访谈称某事发生在2010年，而可核文件显示在2012年。应纠正事件日期及依赖它的先后推论；但若研究问题是受访者如何把此事与另一人生阶段联系，叙述本身仍可作为记忆组织的材料。不能因此推断受访者撒谎，也不能保留错年作为事实。","assumptions":"访谈与日期为教学设定，不指称真实人物或实际档案。","boundary":"说明分用途评价，不进行心理诊断，也不替任何真实口述背书。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：论文、新闻稿和三篇报道都转述同一数据，却被当成五次独立复现。","effect":"存在传播链而非五套底层资料；应保留各自用途与共同来源。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学边界：一个项目的公开仓库没有合同，就断言全部参与者从未持有合同。","effect":"公开仓库的检索范围不能覆盖私人持有和其他档案；结论应停在当前未查到。","sourceIds":["theory"]}],"questionAnswers":[{"question":"看到一份论文正式版与预印本，最先该比较什么？","answer":"版本、样本、结局、分析和口径是否变化，以及共享哪些底层资料；不能直接记两次复现。","basis":"本节原文及上述公开推导"},{"question":"只读了相关两节，能否在来源里写“已阅读全文”？","answer":"不能。应写相关章节已读，并把支持范围限制在实际核查内容。","basis":"本节原文及上述公开推导"},{"question":"口述中一个日期错误，应如何处理其余内容？","answer":"更正日期并检查依赖它的推论；其他内容按其独立证据与用途评价，既不全盘作废也不全盘接受。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-7/figures/section-2-7-1.png","alt":"1855年作品，当时调查与作者解释；2024年数字转录，同一作品的新载体；本讲引用，只用已核相关段；独立底层资料？，另须证明来源关系；全文／章节／摘要，实际读取范围明示；当前未查到，不等于历史从未有。版本示意图，依据Gutenberg页首与1855书名页；两种载体不是两次独立调查。","caption":"版本示意图，依据Gutenberg页首与1855书名页；两种载体不是两次独立调查。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。选中载体可显示日期、版本关系与已读范围。当前未核印本的逐字校勘应保持未核，不能因有数字文件自动完成。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实数字载体与历史作品的版本关系可核，适合展示来源关系和读取范围。"},"openQuestions":[],"taskId":"S-2-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第341—362行；每节精确范围见sourceRefs","claim_support":["2.7：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-use","title":"John Snow 1855，事件与因果限制","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"p.40；pp.51—52","claim_support":["2.7：面谈与拆柄日期记述；停用前已下降的限制。"],"limits":["日期事实不直接支持净效果。"],"access_status":"partially_read"},{"id":"snow-version","title":"John Snow作品及Gutenberg数字版书目信息","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855第二版；Gutenberg release 2024-02-07","locator":"页面首部Release date；书名页第二版和London1855","claim_support":["2.7.1：历史作品1855第二版与数字发布2024为同一作品不同载体。"],"limits":["未作数字转录与印本逐字校勘；载体不构成独立调查。"],"access_status":"partially_read"},{"id":"snow-trace","title":"John Snow 1855，Table I及说明","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"pp.49—51，Table I日期行、Date unknown行和总计；表后逐日下降描述","claim_support":["2.7.2：43个已知日期行加总571，未知日期45，总计616（加总为本讲派生）。","2.7.2：9月6日20、9月7日28，限制严格逐日单调的读法。"],"limits":["原表为最终致死病例发病日与死亡日两列；本讲只算前者。","与snow-use、snow-version为同一作品不同位置，不增加独立研究数；异常不揭示成因。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-7/lecture.md","sourcesPath":"/reading-assets/S-2-7/sources.json","sourceSlicePath":"/reading-assets/S-2-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-7/diagrams.md"},"2.7.2":{"title":"2.7.2　证据独立性与缺陷的传播","lead":"同一批资料换一种分析，确实可能增加知识，却没有增加一批独立样本。发现一个差异，也只应先暂停真正依赖它的结论。","explanation":["原文定位：第357—362行；原文锚点 section-2-7-2；短引文：‘独立性必须相对于所支持的主张判断’。本题源切片逐字附后，讲解与原文分开。","独立性不是一个无条件的“是／否”标签。同一次随机分配的长期随访增加时间和结局信息，但没有增加随机分配次数；同一资料用另一算法复核增加实现和解释检查，但没有新增原始队列。反过来，两个研究题材同名却有不同底样，也不能只按标题把它们强行合并。","来源关系应保留共享数据、共同测量、版本继承与新增观察。独立于哪个环节必须说清：数据可能共享而分析实现独立；测量方法可能共享而对象样本独立。评价一个具体主张时，要识别它对这些环节的依赖，不能把文件数换成证据分数。","发现数值差异时先判断属于同一对象的冲突、不同对象的合法差别，还是显示精度的表面差异。病例数与人次数、累计与新增、发病日与死亡日、整体和阈值子群，都可能不该相等。若真冲突尚未解释，就暂停依赖该数字的精确结论，并沿“源数值→转录→模型输入→派生量→正文”追踪。","加总闭合是一种核查，但不能单独认证每个分项。两个分项一增一减可保持总和不变；反之，发现异常也不能立即指认原因是转录错误、造假或真实变化。先报告可定位差异和受影响范围，不替证据填成因。","对仍有独立依据的其他判断，按其范围继续使用。只有共同来源、关键前提或对象边界失效时，才阻断全部相关输出。逐命题处理使纠错既不掩盖问题，也不把一个局部问题放大成毫无根据的全盘否定。"],"distinctions":[{"leftTitle":"独立数据","leftText":"新增底层观察或队列。","rightTitle":"独立重分析","rightText":"同一底样的不同实现，可发现错误但不多算一批人。"},{"leftTitle":"真实冲突","leftText":"对齐同一对象、单位、时点后仍不能并立。","rightTitle":"合法差别","rightText":"比较的对象、分母或指标本来不同。"},{"leftTitle":"合计闭合","leftText":"分项之和与总数吻合。","rightTitle":"分项正确","rightText":"每项均有正确来源、归类与口径，需更多核查。"},{"leftTitle":"局部异常","leftText":"影响特定数值及派生结论。","rightTitle":"共同前提失效","rightText":"可能阻断所有依赖其的输出，范围更大。"}],"boundaries":["Snow表I的9月6日致死病例发病数20、9月7日28，因此不能把其文字中的“每天减少”机械读为严格单调序列。这个局部反例不抹去整体下降，也不决定转录或原作措辞差异的成因。","本讲只在当前数字转录内复核汇总及这两个日值，没有宣称逐字校勘原始死亡登记簿；43个日期行不是43份独立研究。","571+45=616成立，不证明45个未知日期可以任意分配，也不使完整感染数已知。"],"questions":["同一随机试验增加三年随访，能写成新做了一次随机试验吗？","表格总数等于各项之和，是否足以证明每项正确？","某日数字有争议，为什么不应立刻撤销同书所有判断？"],"diagramPath":"/reading-assets/S-2-7/figures/section-2-7-2.png","caseLinks":[{"title":"Snow表I：核总和，也核文字的强度","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"Snow表I：核总和，也核文字的强度","text":"当前转录的表I列有发病日不明45例；其余43个日期行合计571，总计616。另一个局部检查显示9月6日为20、9月7日为28，故“每天减少”不能作为严格单调的数字命题使用。本节不据这个差异猜测成因，只限制相应表述。","sourceLabel":"Snow 1855第二版，Table I及紧随说明","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷p.49 Table I（1854-08-19至09-30及Date unknown）；pp.50—51表后说明","boundary":"计数对象是最终致死病例的发病时点，部分由病程回推；合计闭合不认证各日值，非单调不否定总体下降，也未识别拆柄效果。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.7.2","start_line":357,"end_line":362,"startLine":357,"endLine":362}],"outputId":"section-2-7-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提一：新信息可以来自新样本、新时点、新测量或新分析；这些新增不是同一种独立性。","前提二：派生结论只依赖其实际输入与前提，因此错误传播有特定路径。","连接：先给数字对齐对象、口径、单位、窗口与精度，再检查是真冲突还是合法差别；真冲突沿依赖路径暂停。","结论：独立性和降级均逐主张登记；未受影响的独立依据不随局部异常一并作废。","实算：Snow表I已知发病日的43个日期行合计571，加发病日不明45，等于表中总数616；此一致只检查汇总，不证明各日期分配正确。"],"teachingExamples":[{"title":"教学数学构造：合计相同仍能两项都错","text":"真实给定分项为40和60，总计100；若转录成45和55，总计仍是100。总数核对通过并不保证分项正确。若正文只使用已独立核对的总量，未必受此分配错误影响；若使用两组比例或差，则必须暂停相关推断。","assumptions":"这组数字纯为教学构造，不是Snow或任何实际数据。","boundary":"演示误差传播，不指认任何真实作者造假或某处转录错误。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Snow表I中9月6日20、9月7日28，与表后“每天减少”的严格单调读法不相容。","effect":"暂停严格逐日单调主张；仍可保留有据的总体下降描述，但不得据此推出移柄净效果。","sourceIds":["snow-trace"]},{"identity":"constructed_boundary","text":"教学构造40+60与45+55均为100。","effect":"合计闭合不能独自认证每个分项；需沿具体派生量追查。","sourceIds":["theory"]}],"questionAnswers":[{"question":"同一随机试验增加三年随访，能写成新做了一次随机试验吗？","answer":"不能。新增时间与结局信息值得保留，但分配和原始队列没有因此复制。","basis":"本节原文及上述公开推导"},{"question":"表格总数等于各项之和，是否足以证明每项正确？","answer":"不足。分项误差可能抵销，仍需核源值、单位、归类和转录。","basis":"本节原文及上述公开推导"},{"question":"某日数字有争议，为什么不应立刻撤销同书所有判断？","answer":"先确定哪些结论真正依赖该数字；有独立材料的其他判断可以保留。若发现共同来源或边界失效，才扩大暂停范围。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-7/figures/section-2-7-2.png","alt":"源表日期值，9月6日20／7日28；局部派生判断，并非严格逐日下降；限制强表述，保留总体趋势边界；43个已知日期行，合计571；未知日期45，571+45=616；总和核对通过，不认证各分项。真实表值与本讲精确加总：Snow1855表I pp.49—51。两条核查路线回答不同问题，不推断异常成因。","caption":"真实表值与本讲精确加总：Snow1855表I pp.49—51。两条核查路线回答不同问题，不推断异常成因。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。可选择“总量结论／每日比例／严格单调”，高亮各自依赖；模拟修改只能标教学敏感性，不能改写原表或抹去旧记录。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一来源中的汇总与局部变化可精确核算，能直接展示差异分类与结论限缩，不伪造异常原因。"},"openQuestions":[],"taskId":"S-2-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第341—362行；每节精确范围见sourceRefs","claim_support":["2.7：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.1：术语、合同、论证责任和原文边界；不据此认证经验事实","2.7.2：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-use","title":"John Snow 1855，事件与因果限制","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"p.40；pp.51—52","claim_support":["2.7：面谈与拆柄日期记述；停用前已下降的限制。"],"limits":["日期事实不直接支持净效果。"],"access_status":"partially_read"},{"id":"snow-version","title":"John Snow作品及Gutenberg数字版书目信息","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855第二版；Gutenberg release 2024-02-07","locator":"页面首部Release date；书名页第二版和London1855","claim_support":["2.7.1：历史作品1855第二版与数字发布2024为同一作品不同载体。"],"limits":["未作数字转录与印本逐字校勘；载体不构成独立调查。"],"access_status":"partially_read"},{"id":"snow-trace","title":"John Snow 1855，Table I及说明","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"pp.49—51，Table I日期行、Date unknown行和总计；表后逐日下降描述","claim_support":["2.7.2：43个已知日期行加总571，未知日期45，总计616（加总为本讲派生）。","2.7.2：9月6日20、9月7日28，限制严格逐日单调的读法。"],"limits":["原表为最终致死病例发病日与死亡日两列；本讲只算前者。","与snow-use、snow-version为同一作品不同位置，不增加独立研究数；异常不揭示成因。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-7/lecture.md","sourcesPath":"/reading-assets/S-2-7/sources.json","sourceSlicePath":"/reading-assets/S-2-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-7/diagrams.md"},"2.8":{"title":"2.8　核心词语锁","lead":"“成本”“修复”“选择”“责任”都是日常词，却各自带着不同的判断条件。锁住词义，是为了防止一句话在推理中悄悄换了意思。","explanation":["原文定位：第363—380行；原文锚点 section-2-8；短引文：‘不能以日常语言的宽泛含义替代’。本题源切片逐字附后，讲解与原文分开。","成本首先是某种量：类型、单位、时间窗、核算边界和承担位置都要写出。现金、工时、风险和注意力不能直接相加；若要转换，需要明确的计价、测量或会计映射。某处少支出，不代表同型成本必然转到另一处，更不证明存在跨领域统一的成本守恒。资源被占用是一项观察，是否与其他量可比较是另一项工作。","外部性在这里有两步：先有跨边界因果通道与分布位置，再说明经济模型或真实制度、会计规则把哪一影响排除在决策核算之外。只有第一步，可称跨边界溢出或影响，不能用词语提前指定责任。第二步不要求先裁定法定责任；无法确定谁负法律责任，也不妨碍记录已有证据的跨界伤害。","跨界分析也要选对合同。C7处理其限定条件下的溢出与分布位置，不覆盖所有经济外部性或一般传播。确有尺度变化才另核D3/E5；主张闭合失败、对象或干预转换的正式支持时，才检相应G4，不能一出现“外部”二字就强加所有尺度流程。","修复要在结果前公开目标同一性K*或功能F*：准备恢复哪一种对象身份或哪项功能。修复可以允许新实现，不必恢复历史原样；恢复既定功能也不等于价值改善。目标是否正当、由谁决定、谁能实施，仍由N和O审查。不能见结果后改目标，说只要出现任意变化就是修复成功。","选择有三种语义。系统筛选是变异、差异保留和再生产的过程；它不必有意图。行动主体选择包含主体在条件下作决定；不能将它等同环境筛选。治理选择还要比较方案、规范前提与授权；看到一个结果被保留下来，不等于有人正当地选择了它。","责任与授权分开登记承接载体、同型成本承担者、受益者、停止权和责任主体。实际执行者、能力最强者、最受影响者、最显眼者或最懂情况者，都不能单凭这一属性被指定为无限负责的人。观察范围或解释置信度扩大，也不扩大管辖权J。","义务的理由可能包含承诺、角色、因果贡献、受益、能力和适用规范，需公开它们怎样共同支持具体义务及其边界。有限义务不把任何人变成单方、无限、不可退出的承接者；对停止、转交、期限和救济的安排，本身就是责任判断的一部分。"],"distinctions":[{"leftTitle":"支出减少","leftText":"特定边界、单位和窗口的金额变化。","rightTitle":"统一成本降低","rightText":"跨不同承担者和量型的更强判断，需转换与分配依据。"},{"leftTitle":"跨界影响","leftText":"有因果和分布位置。","rightTitle":"外部性","rightText":"还要明确排除在决策核算外的规则，不等于先判法律责任。"},{"leftTitle":"修复","leftText":"达到事前K*或F*。","rightTitle":"价值改善","rightText":"目标正当与后果可接受，需额外规范评价。"},{"leftTitle":"系统筛选","leftText":"差异保留的过程。","rightTitle":"主体／治理选择","rightText":"前者需主体决策，后者还需规范和权限。"},{"leftTitle":"承接者或受益者","leftText":"记录谁实际承受或得到什么。","rightTitle":"责任主体","rightText":"由多种理由和规范支持的有限义务，非自动等同。"}],"boundaries":["本节是专门语义和使用条件，不能从术语定义推出世界存在某种普遍成本守恒或统一目的。","未能定法律责任不等于不能记录伤害；记录伤害也不等于已经指定负担份额或处置权。","观察能力与授权是不同尺度轴。即使掌握全部情况，仍须核单一对象、动作、地域、期限和撤回条件下的权限。","修复目标不能事后任意改写；需要变更时另建版本，保留原目标下的结果。"],"questions":["记录污染已跨界伤害他人，是否必须先判明法定责任才可报告影响？","某功能达到事前目标，为什么仍不能直接宣布“这是好方案，可以立即实施”？","甲受益最多、乙执行最多，能否只据此指定唯一责任主体？"],"diagramPath":"/reading-assets/S-2-8/figures/section-2-8.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"2.8","start_line":363,"end_line":380,"startLine":363,"endLine":380}],"outputId":"section-2-8","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：同一个词在日常语言中常同时携带描述、评价和行动含义；混用会让后一步偷借前一步没有提供的依据。","连接一：成本先同型、同单位或有合法转换；外部性先查因果与排除规则；修复先定K*／F*；选择先定系统、主体或治理语义。","连接二：涉及责任时，分别检查角色、因果、承诺、受益、能力和规范，而不是从一个可见身份直接推出全责。","结论：词语锁让每一步缺什么都可见；不能借“修复成功”跳过价值审查，也不能借“我懂”跳过授权。","证据与规范责任：跨界效应和承担位置需要材料，排除规则需要模型或制度依据，义务及行动上限需要规范与有效授权。"],"teachingExamples":[{"title":"教学构造：预算节省与时间负担不能直接守恒","text":"假设方案使机构每月支出减少100元，却让使用者多等待3小时。先分别记录人民币/月和小时/人次及承担者，不能写“总成本减少97”或“100元完全转成3小时”。若采用每小时v元的明确估值，才可在限定人数与窗口下写100−3v；这个v包含价值与测量选择，不能伪装为世界统一常数。","assumptions":"100元和3小时均为教学设定；只有单个使用者、同一窗口等条件明定后才可作示意换算。","boundary":"不估计真实方案的净福利，也不据数字分配法定责任。"},{"title":"教学构造：功能修复不等于一切回到旧样","text":"假设事前F*是“给定负载下读数误差不超过e”，更换部件后按有效测量达到F*，可以在该合同内称功能恢复；不必声称所有旧部件被复原。若新部件带来额外安全风险或侵犯他人权益，功能达标也不独自证明方案正当。","assumptions":"设备、负载、误差界和结果均是条件教学，不是实测报告。","boundary":"修复资格只限所定功能；正当性、实际证据和实施权限另核。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学边界：最懂系统的人被要求永久承担所有维护费用，只因“只有你有能力”。","effect":"能力可成为一种责任理由，却不能单独推出无限且不可退出的义务。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"教学边界：某种组织形式在竞争中存活，被写成“系统有意选择了最正当制度”。","effect":"把差异保留偷换成主体意图和规范优越性；两项都缺额外依据。","sourceIds":["theory"]}],"questionAnswers":[{"question":"记录污染已跨界伤害他人，是否必须先判明法定责任才可报告影响？","answer":"不必。因果伤害记录、核算排除规则和法定责任是不同工作；有据的影响可先保留。","basis":"本节原文及上述公开推导"},{"question":"某功能达到事前目标，为什么仍不能直接宣布“这是好方案，可以立即实施”？","answer":"功能修复不包办价值、风险、权限、行动上限和停止条件，须另核N与O。","basis":"本节原文及上述公开推导"},{"question":"甲受益最多、乙执行最多，能否只据此指定唯一责任主体？","answer":"不能。应公开承诺、角色、因果贡献、受益、能力与适用规范的关系，并限定义务。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-8/figures/section-2-8.png","alt":"成本，类型／单位／窗／承担；外部性，跨界因果＋核算排除；修复，结果前 K* 或 F*；选择，筛选／主体／治理分开；责任，多种理由＋有限义务；授权，对象／动作／期限／撤回。术语条件图，依据2.8；各格不能互代，不表示成本守恒、目的等级或责任自动转移。","caption":"术语条件图，依据2.8；各格不能互代，不表示成本守恒、目的等级或责任自动转移。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。可点击某个词展示缺字段后的结论上限。改变核算边界、修复目标或授权动作时，须新建或修订对应合同，不自动扩张其余含义。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是词义和使用合同的锁定，教学反例直接揭示单位、目标、意图和责任偷换；没有为了定义硬配史实。"},"openQuestions":[],"taskId":"S-2-8","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第363—380行；每节精确范围见sourceRefs","claim_support":["2.8：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-2-8/lecture.md","sourcesPath":"/reading-assets/S-2-8/sources.json","sourceSlicePath":"/reading-assets/S-2-8/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-8/diagrams.md"},"2.9":{"title":"2.9　字段缺失与可见性状态、降级、暂停与退出","lead":"空白不能只填“暂无”。先说明是还不知道、概念不适用、目前看不到，还是有资料但应受保护；再决定究竟限制哪一条结论、哪一项行动。","explanation":["原文定位：第381—394行；原文锚点 section-2-9；短引文：‘降档逐命题登记其依赖和缺失影响’。本题源切片逐字附后，讲解与原文分开。","未知：原则上可知，当前证据不足。需要说明缺什么材料，什么可改变状态。不适用：字段在当前对象合同中没有合法对应物，要给理由；它不是“难填所以略过”。例如纯自然过程没有行动主体与授权概念时，J轴可不适用，但研究者对该过程实施干预的行为仍可能需要授权。对象和动作不能混为一谈。","不可观察：受测量能力、时间窗或通道限制，当前无法取得材料。它不等于不存在，也不等于永远不可知；改变窗口或测量可能改变可见性，但不能假称已经获得缺失事实。为保护而不公开：材料确实存在，公开会触犯隐私、安全或明确保护，应记保护依据、最小范围、期限与可信复核路径。","四状态同时说明知识与可见性，不能偷偷当作真假标签。未知值不能补成0，不适用不能与零值相加，不可观察不能记成没有，保护不公开也不能写成研究者没有资料。实际仍应按合同说明对应状态，必要时进一步记录可信复核是否可达。","缺关键变量、适用性未处理、核心通道不可观察，或保护性材料不能可信复核时，依受影响主张降为候选、问题清单或描述。这里不是把所有结论机械降到同一级，而是逐条看它缺的条件是否必要。事实计数可有依据，机制解释仍未决，两者可以并存。","行动边界另判断：授权不明、不可逆伤害风险、申诉与停止不可达，或超出专业能力时，应暂停现实处置并转入适当程序。可以继续安全的材料澄清与方案讨论，不表示可以趁“试探”之名先行实施。退出或撤回某个主张，也不需要抹去真实失败记录。","局部前提失效只影响依赖它的输出；全局来源、共同前提或对象边界失效，则阻断所有相关输出。区别在实际依赖范围，不在愿不愿意承认问题。保留未知和降级让证据上限与权力边界可见，本身是负责任的结论。"],"distinctions":[{"leftTitle":"未知","leftText":"可能得到答案，目前依据不够。","rightTitle":"不适用","rightText":"这个字段对当前对象没有合法含义，须理由。"},{"leftTitle":"不可观察","leftText":"当前窗口或通道拿不到观察。","rightTitle":"不存在","rightText":"关于世界的否定事实，不能由前者自动推出。"},{"leftTitle":"保护性不公开","leftText":"有材料，限缩公开并安排可信复核。","rightTitle":"无人能够复核","rightText":"会进一步限制结论，保护不是强断言豁免。"},{"leftTitle":"结论降级","leftText":"减少证据可支持的强度。","rightTitle":"现实处置暂停","rightText":"因权限、伤害、申诉或能力等停止行动，理由可独立。"}],"boundaries":["四种字段状态不等于四种世界真值；不能把unknown、not_applicable或不可见都编码为数值0后计算平均。","保护性不公开不得成为逼迫披露的理由，也不能成为不可复核强主张的永久通行证。","局部失效不一律污染全局；但若对象身份或共同来源整体不可信，必须扩大暂停到所有相关判断。"],"questions":["一项材料存在但因隐私不公开，应该填“未知”以省事吗？","某机制的关键输入缺失，但独立描述数据可信，是否全部结论都要撤销？","模型很有把握，但行动授权不明，可以先试一次吗？"],"diagramPath":"/reading-assets/S-2-9/figures/section-2-9.png","caseLinks":[{"title":"古DNA样本身份未决时的局部排除","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"caseNotes":[{"title":"古DNA样本身份未决时的局部排除","text":"Skov等2022年原文说明，无法确信Chagyrskaya E是独立于D的另一个个体，因此从后续分析移除了E样本。本讲把这用作按具体身份缺口限制使用的例子，不给作者追授Xikari状态编号。","sourceLabel":"Skov et al. 2022，样本E的处理说明","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","sourceLocator":"Genetic relationships，Chagyrskaya E污染、校正及“cannot be confident…distinct individual”段","boundary":"只支持该样本的处理及其理由；本讲未复算遗传数据，不能据此断言其余所有结论无误。","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/"}],"sourceRefs":[{"section":"2.9","start_line":381,"end_line":394,"startLine":381,"endLine":394}],"outputId":"section-2-9","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：相同的空白表面可对应不同原因，若统一填零或否，便会改变对象事实或字段语义。","分类：对每个字段给明示状态与理由；明确哪些材料已经存在、哪些缺失、哪些不宜公开。","依赖检查：对每条主张列其必要输入；缺必要输入时限制该主张，有独立依据的其他主张保留。","行动检查：证据不完整与授权不完整各自可能阻止处置；严重不可逆风险、能力边界和停止不可达不能靠模型置信度覆盖。","结论：按缺口范围降级、暂停或退出，并保留重新评价所需材料与旧记录；不把无法观察当作不存在。"],"teachingExamples":[{"title":"教学构造：四个空格，四种不同答案","text":"假设一张分析表含：尚未取得的某日总量，记未知；纯自然过程的主体授权字段，说明对象无行动主体后记不适用；被设备量程限制而测不到的瞬时峰值，记不可观察；已存在但涉及隐私的个体记录，说明保护依据、范围、期限与复核者后记保护性不公开。不能把四格都填0。","assumptions":"四项是教学场景，不含真实个人资料、实验或现场测量。","boundary":"具体合法性与保护程序需按真实场景另核；例子不授权收集、披露或处置。"},{"title":"教学构造：一条链缺失，不把整页清零","text":"假设独立计数记录支持“队列中有20项请求”，而解释“拥堵由接口A失灵造成”依赖尚未取得的接口日志。可保留20项这个有限描述，机制保持候选；若后来发现计数把同一请求重复计入，则该计数及其派生率也须重查。","assumptions":"20和接口情境为教学设定；独立性是明示前提而非已证事实。","boundary":"不声称实际系统存在20项或接口故障；只示范逐主张降级。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Skov等未能确认Chagyrskaya E是不同于D的独立个体，因此将E样本移出后续分析。","effect":"身份不明影响该样本的使用资格，而非自动使所有其他有据的亲缘分析失效。","sourceIds":["skov-local"]},{"identity":"constructed_boundary","text":"教学边界：研究者把“没有权限看到资料”填写为“资料不存在”，据此排除某种解释。","effect":"可见性限制被冒充否定事实，相关排除判断应撤回到未决。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一项材料存在但因隐私不公开，应该填“未知”以省事吗？","answer":"不应偷换。记录保护性不公开及依据、最小范围、期限、可信复核路径；公众或当前分析者能支持多少结论再另说明。","basis":"本节原文及上述公开推导"},{"question":"某机制的关键输入缺失，但独立描述数据可信，是否全部结论都要撤销？","answer":"不必。降级依赖缺失输入的机制判断，保留独立描述；若共同来源或对象边界失效再扩大范围。","basis":"本节原文及上述公开推导"},{"question":"模型很有把握，但行动授权不明，可以先试一次吗？","answer":"不能据置信度越权。应暂停相关处置，补权限与停止、申诉、风险等程序；提出可逆试探方案不等于准许实施。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-9/figures/section-2-9.png","alt":"未知，原则可知，当前不足；不适用，无合法对应，说明理由；不可观察，窗口／测量／通道受限；保护性不公开，依据／范围／期限／复核；逐主张查依赖，降级或保留独立判断；行动边界另查，暂停／退出／补程序。状态与决策示意，依据2.9；四类状态不能合并成零值，降级和暂停有不同依据。","caption":"状态与决策示意，依据2.9；四类状态不能合并成零值，降级和暂停有不同依据。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。选择字段状态后，只高亮依赖该字段的判断；若切换为共同来源失效，扩大到全部相关输出。不得自动把未知填成模型猜测值。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实研究公开身份不确定和局部排除，能展示缺口对应使用范围；与前题同案但新增证据处理角度。"},"openQuestions":[],"taskId":"S-2-9","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第381—394行；每节精确范围见sourceRefs","claim_support":["2.9：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"skov-local","title":"Skov et al., Genetic insights into the social organization of Neanderthals","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9581778/","source_type":"primary","version_or_date":"2022-10-19，Nature610:519—525","locator":"Genetic relationships，Chagyrskaya E段及Table1注记","claim_support":["2.9：作者无法确认E为不同个体，将其移出后续分析。"],"limits":["同一论文的局部处理说明；未复算数据，不认证其他所有结论。","不把现实研究倒记为Xikari正式状态实例。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-9/lecture.md","sourcesPath":"/reading-assets/S-2-9/sources.json","sourceSlicePath":"/reading-assets/S-2-9/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-9/diagrams.md"},"2.10":{"title":"2.10　多圈层对象的方法边界","lead":"多画几个圈，不会让解释自动更好。但某个圈在预测上没帮忙，也不等于它的成员事实、责任或权限就不存在。先把用途说清。","explanation":["原文定位：第395—400行；原文锚点 section-2-10；短引文：‘为描述已有依据的责任、成员差异或事项权限保留对象，不必先证明它增加预测准确率’。本题源切片逐字附后，讲解与原文分开。","家庭、组织、平台群体、职业社群和文化类别首先都须作为明确对象来声明：边界、成员、角色、通道、时间窗与K同一性判据。名字或聚类结果本身不会产生天然实体；文书、关系和暴露记录却可以各自支持相应对象事实，不能因还没有G1支持就全部否认。","如果主张某种分组带来解释或前瞻增益，需要与不分组、单圈层等适当简单基线比较，正式G1资格另按其合同建立。这里的目标是“这种分组对这项任务有没有帮助”，不同于“这个家庭或机构有没有文书与成员关系”。二者可能一个有据，另一个未获支持。","平行、嵌套与重叠必须声明比较维度。成员集合交叠，不等于权限重叠；空间包含，不等于组织隶属；两圈在一个维度平行，也可能在另一维度共享成员。竞争描述可用集合约束，即某一窗口的可选行动或资源条件发生限制；临时描述期限或持续性，两者可以与嵌套、交叠等关系并存，不是互斥标签。","潜在桥接、实际传递和传递效应三项分别取证。同一个人同时属于两群，可是潜在桥；要说消息、资源或暴露真传过去，要有实际事件；要说这次传递造成结果，还要因果比较与机制材料。存在边或共同成员，不等于已证明传播，更不等于传播者当然负全部责任。","新增圈层前应说明它回答哪个必要问题，删掉后损失哪种区别，以及新增测量和隐私成本。如果只是把所有背景都圈起来，却说不出用途，可以先保留为环境条件或变量候选。复杂模型没有稳定比较支持时，降低相应增益主张，优先用足够的简单模型。","保留圈层也可以是为了有据的责任、成员差异或事项权限，这些用途无需以预测准确率为准入门。简化预测模型不应顺手删去人的权利或真实组织边界。描述、预测和规范治理三种用途各守自己的证据与授权要求。"],"distinctions":[{"leftTitle":"对象事实","leftText":"成员、关系、文书或暴露记录所支持的内容。","rightTitle":"分组增益","rightText":"分组比基线多解释或预测了什么，需另一比较。"},{"leftTitle":"共同成员／潜在桥","leftText":"具备某种连接可能。","rightTitle":"实际传递及效果","rightText":"具体事件已发生且是否影响结果，分别取证。"},{"leftTitle":"成员重叠","leftText":"集合有公共元素。","rightTitle":"权限重叠","rightText":"特定事项与动作授权交叉，不能由成员集合推得。"},{"leftTitle":"足够的简单模型","leftText":"按当前任务用较少复杂度。","rightTitle":"删除权利和责任对象","rightText":"是另一规范动作，不能由预测无增益自动推出。"}],"boundaries":["缺少G1增益证据不撤销文书或关系支持的对象存在；反过来，机构名称真实也不证明它对某项预测有用。","历史水暴露案例只显示居住地点与接触通道可能不重合；不因此推出所有家庭或跨圈关系均能传播某种东西。","因隐私成本不值得新增某圈层时，应保留必要的未知和范围限制，而不是隐蔽地搜集个人关系填表。"],"questions":["新增一个圈层后预测没有改进，能否据此否定它的成员记录？","一个人同时在两个群里，足以证明消息已经传播吗？","两个圈的成员交叠，能否直接给它们标为“管辖权重叠”？"],"diagramPath":"/reading-assets/S-2-10/figures/section-2-10.png","caseLinks":[{"title":"Hampstead饮水记录：空间圈与接触圈不重合","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"caseNotes":[{"title":"Hampstead饮水记录：空间圈与接触圈不重合","text":"Snow原作第44页记载，一位住在Hampstead且很久未到Broad Street的妇人，仍由每日运水车（原文cart）取得该处泵水。本节的观察点不是重新估计病因，而是：居住边界不能直接代替实际供水接触边界。","sourceLabel":"Snow 1855第二版，Hampstead段","sourceUrl":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","sourceLocator":"印刷p.44，Hampstead West End病例段，随后叙述其侄女的饮水与发病","boundary":"这是Snow依据家属与登记的历史记述；本讲不建立全人群网络，不把送水边独自当作净因果效果。","href":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html"}],"sourceRefs":[{"section":"2.10","start_line":395,"end_line":400,"startLine":395,"endLine":400}],"outputId":"section-2-10","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：分组可以有成员或文书依据，也可以只由分析者提出；两种对象身份必须分明。","用途分流：描述成员与权限时取相关记录；声称分组增益时做相称基线比较；声称传播机制时核通道、事件和效果。","关系核对：按成员、空间、组织或权限等声明维度判断平行、嵌套和重叠，并单独记录竞争约束和期限。","复杂度判断：新增圈层须保留必要区别且成本相称；无稳定增益证据时不夸大预测价值，但不撤销独立有据的成员与权责事实。","结论：多圈层是任务相对的对象组织方式，不是命名越多越真实，也不是预测分数决定一切对象是否值得保留。"],"teachingExamples":[{"title":"教学集合构造：重叠不是同一个关系","text":"设成员圈A={甲,乙}、B={乙,丙}，所以A∩B={乙}，两圈成员重叠；若某事允许行动集合分别为U_A={a,b}、U_B={b,c}，可共同满足的动作是b。若改为U_B={c}，共同可行动作为空。成员重叠是否存在与行动约束是否相容是两项不同判断，不能从乙同时在两圈推出他有权执行所有动作。","assumptions":"人物、圈层和动作全部是教学符号；行动集合由假设给定而非现实授权。","boundary":"只演示集合关系及约束，不认定现实组织、权利、责任或实际传播。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Snow记录住在Hampstead、很久未到Broad Street的人，由每日运水车（原文cart）送去泵水。","effect":"仅按泵旁居住边界分组可能遗漏实际暴露通道；需要把地理圈与供水接触分别核对。","sourceIds":["snow-circles"]},{"identity":"constructed_boundary","text":"教学边界：一个合法责任主体在某模型中没有提高预测准确率，因此被从责任登记中删除。","effect":"把预测用途当作权责对象准入门；应保留独立有据的责任与事项权限。","sourceIds":["theory"]}],"questionAnswers":[{"question":"新增一个圈层后预测没有改进，能否据此否定它的成员记录？","answer":"不能。降低的是相应预测增益主张；真实成员与文书关系按原有依据保留。","basis":"本节原文及上述公开推导"},{"question":"一个人同时在两个群里，足以证明消息已经传播吗？","answer":"不足。先有潜在桥，再核实际消息、时间和接收；效果还要进一步证据。","basis":"本节原文及上述公开推导"},{"question":"两个圈的成员交叠，能否直接给它们标为“管辖权重叠”？","answer":"不能。需要在特定对象、事项、动作、期限下核授权，而不是用成员交集替代。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-10/figures/section-2-10.png","alt":"候选圈层，边界／成员／角色／T／K；对象事实，文书／关系／暴露记录；分组增益主张，与简单基线比较；潜在桥接，共同成员或接口；实际传递，事件／版本／时间；传递效果或行动权限，各自追加证据／授权。用途示意图，依据2.10；上路的预测增益不是对象存在和权利的唯一准入门，跨圈事实不自动授权。","caption":"用途示意图，依据2.10；上路的预测增益不是对象存在和权利的唯一准入门，跨圈事实不自动授权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。选择“描述／预测／传播／权责”时显示不同材料责任；切换成员、空间或权限维度时重新判断重叠，不沿用其他维度的标签。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"具体历史供水联系能显示空间分组与实际通道不同，适合多圈层边界问题；不把该例升级成通用网络机制。"},"openQuestions":[],"taskId":"S-2-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第395—400行；每节精确范围见sourceRefs","claim_support":["2.10：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"snow-circles","title":"John Snow 1855，Hampstead West End饮水记述","url":"https://www.gutenberg.org/cache/epub/72894/pg72894-images.html","source_type":"primary","version_or_date":"1855年第二版；数字转录版2024-02-07","locator":"印刷p.44，Hampstead妇人及运水车（原文cart）送水段","claim_support":["2.10：远离Broad Street居住者仍通过送水联系该泵，空间位置与接触通道不等同。"],"limits":["历史调查记述，未构建完整暴露网络，不单凭个案识别净因果效果。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-10/lecture.md","sourcesPath":"/reading-assets/S-2-10/sources.json","sourceSlicePath":"/reading-assets/S-2-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-10/diagrams.md"},"2.11":{"title":"2.11　人格与行动者状态的方法边界","lead":"一次沉默、一次热情或一个分数，先是某个时点、某个场合里的材料。要把它解释为稳定人格，必须跨过时间、情境、测量和用途的额外检查。","explanation":["原文定位：第401—406行；原文锚点 section-2-11；短引文：‘人格只作为有证据等级的慢变量假设进入’。本题源切片逐字附后，讲解与原文分开。","本节把人格放在“有证据等级的慢变量假设”位置，而不是把人定格成一种本体。行为表现可以包含相对持续倾向，但一次行为、自述、他述、量表分数或模型聚类都不能单独生成稳定人格结论。类别命名不能代替跨窗口、跨情境和测量的依据。","至少保留角色激活、物质约束、即时情绪、策略、文化规范、观察者位置及测量偏差等竞争解释。相同的少言，可能出现在需专注的任务、语言不熟的情境或不愿披露的讨论；单一表现没有把这些解释区分开。列出候选不是宣称其中任何一种已真实发生。","慢、中、快三个时间带帮助防止时间偷换：慢带对应需较长窗口支持的持续倾向假设；中带可对应阶段性角色、目标或资源状态；快带可对应当前情绪和局部互动。它们是随任务和对象声明的时间尺度，不是所有人统一的天数表，也不是把快变量自动平均成慢人格。","每项变量都要绑定观察窗、来源、反证、圈层条件、隐私和允许用途。跨场景使用时，要问原来的行为机会和角色是否仍在、报告是否可比、该推断是否会越出同意的用途。多个来源若只是转述同一个事件，不能假装跨情境重复观察。","框架不作临床或精神医学诊断；沉默、拒绝披露和不可观察都不是病理证据。模型可提出变量候选与最小检验，却不能替现实个人填写取值，更不能凭推断扩大管理权限。一个谨慎结果可以是“现有材料不足以区分持续倾向与情境反应”。"],"distinctions":[{"leftTitle":"当下状态","leftText":"某个窗口的表现或自报。","rightTitle":"慢变量假设","rightText":"跨窗口相对持续倾向，需要更多、相称的证据。"},{"leftTitle":"描述分布的均值","leftText":"多次表现的一种汇总。","rightTitle":"每次都这样","rightText":"关于单次行为的强预测，不由平均推出。"},{"leftTitle":"量表或聚类标签","leftText":"一种测量或模型表示。","rightTitle":"人的本体与临床诊断","rightText":"不能由一个标签产生，临床诊断也不在本框架职责内。"},{"leftTitle":"不愿披露","leftText":"个人对信息使用的边界。","rightTitle":"病理或特质证据","rightText":"需要独立合格依据，不能从拒绝本身推断。"}],"boundaries":["Fleeson的经验抽样研究使用学生自报材料，聚合参数稳定性主要按同一短窗口随机拆半比较；不能说它证明人格终生不变或每次行为可预测。","材料不足不意味着这个人没有持续倾向；它只限制当前能够作出的判断。","不得用本节实例对现实特定人作人格评分、心理状态断言或高影响筛选；本讲未对任何读者开展测量。"],"questions":["某人一次很热情，是否就足以确认其稳定外向？","重复报告的平均值很稳定，是否代表每一时点都一样？","当事人不愿披露，模型能否根据其他弱线索自动补全健康或人格？"],"diagramPath":"/reading-assets/S-2-11/figures/section-2-11.png","caseLinks":[{"title":"2001年经验抽样研究：状态变化与汇总稳定并存","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"caseNotes":[{"title":"2001年经验抽样研究：状态变化与汇总稳定并存","text":"Fleeson用三项学生经验抽样研究，在约两至三周内多次收集日常行为自报。研究同时看到个体内变化和聚合分布参数的稳定性。这里的“稳定”主要来自同一观察窗口中随机拆半的比较，不是终生不变的证明。","sourceLabel":"William Fleeson, 2001, Traits as Density Distributions of States","sourceUrl":"https://simine.com/407/readings/Fleeson_2001.pdf","sourceLocator":"JPSP80(6):1011—1027；p.1011摘要；pp.1014—1015、1019—1020、1022方法；p.1020 Table4注及pp.1023—1024讨论","boundary":"原作是短窗口自报研究，未提供对本讲读者或任何指定人的人格诊断。没有把分半稳定性说成终身稳定，也未复算原始数据。","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"sourceRefs":[{"section":"2.11","start_line":401,"end_line":406,"startLine":401,"endLine":406}],"outputId":"section-2-11","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：观察行为是某人、某时、某情境、某观察方式下的材料，不直接等同跨情境稳定属性。","连接：稳定倾向假设需要相应时间窗口和可比重复材料，并与角色、约束、情绪、策略及测量解释竞争。","证据分类：分别记自述、他述、量表、行为记录和模型输出的支持范围，不把一个来源或一次事件重复计证。","结论：最多在有据的窗口、情境和用途内保留慢变量候选；未区分的解释保持未决，不能升格成人的固定本质。","用途责任：任何涉及隐私与行动的进一步资料取得或使用都另核必要性和权限；本节知识框架不赋予诊断或人员处置资格。"],"teachingExamples":[{"title":"教学数学构造：同一均值不说明每次相同","text":"假设只为演示汇总，甲的四个状态分值是1、1、7、7，乙是4、4、4、4，两者均值都是4，但变化幅度不同。只知道均值无法知道某次会是几分；又因为仅四次且情境未明，也不能据这组设定确立任何真实人格。","assumptions":"数字是人为构造的同单位分值，甲乙不是实际受试者；不赋予临床含义。","boundary":"例子只否定“均值相同→行为分布相同／每次相同”，不提供现实人格证据。"},{"title":"教学候选：一次拒绝发言","text":"面对一个假设场景“某人在一次会议拒绝发言”，可列候选：角色不要求其发言、材料不足、当下疲倦、策略性保留、不愿在此披露，或较持续的偏好。只凭该行为不能选定一个，更不能把它写成健康或人格结论；首先应问当前任务是否真的需要取得更多个人信息。","assumptions":"情境完全假设，候选不代表对任何真实人物的判断。","boundary":"不建议强迫披露或开展未授权测验；保持未知是合法结果。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Fleeson 2001年三项经验抽样研究同时报告较大的个体内状态变化与聚合分布参数的稳定性。","effect":"短时波动与聚合稳定可以并存；不能用一次行为或一个平均值覆盖全部情境。","sourceIds":["fleeson-state"]},{"identity":"constructed_boundary","text":"教学边界：观察者把拒绝提供私人信息记为“回避型人格证据”。","effect":"拒绝披露不是病理或稳定人格的单独证据；应撤去标签，保留信息边界。","sourceIds":["theory"]}],"questionAnswers":[{"question":"某人一次很热情，是否就足以确认其稳定外向？","answer":"不足。一次表现只覆盖当时情境；需可比的多窗口材料及竞争解释，且用途应正当。","basis":"本节原文及上述公开推导"},{"question":"重复报告的平均值很稳定，是否代表每一时点都一样？","answer":"不代表。平均值稳定可以与较大个体内变化并存；还要看分布和情境。","basis":"本节原文及上述公开推导"},{"question":"当事人不愿披露，模型能否根据其他弱线索自动补全健康或人格？","answer":"不能。保持未知并核必要性、隐私和用途；不可将沉默当病理证据或推断授权。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-11/figures/section-2-11.png","alt":"慢带，持续倾向的证据假设；中带，角色／阶段目标／资源；快带，当前情绪／局部互动；材料合同，观察窗／来源／情境；竞争解释与反证，测量／角色／约束；有限允许用途，隐私／非诊断／不越权。概念图，依据2.11；时间带由对象与任务声明，未绘制真实人格曲线或对个人打分。","caption":"概念图，依据2.11；时间带由对象与任务声明，未绘制真实人格曲线或对个人打分。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换时间窗或圈层时，显示哪些变量假设需重新核查；三带不按日历阈值自动分类，不把拒绝披露填成病理值。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"一手经验抽样设计能说明状态与汇总倾向的不同时间含义，适合作为方法边界例，不作为人格测验。"},"openQuestions":[],"taskId":"S-2-11","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第401—406行；每节精确范围见sourceRefs","claim_support":["2.11：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"fleeson-state","title":"Fleeson, Toward a Structure- and Process-Integrated View of Personality: Traits as Density Distributions of States","url":"https://simine.com/407/readings/Fleeson_2001.pdf","source_type":"primary","version_or_date":"2001-06，DOI10.1037/0022-3514.80.6.1011","locator":"JPSP80(6):1011—1027；摘要、三项研究方法、Table4注和General Discussion","claim_support":["2.11：学生经验抽样，约2—3周多次行为自报；个体内变化与聚合参数稳定并存。","2.11：相关稳定性以同一窗口随机拆半比较，不能直接解释为长期不变。"],"limits":["已读所用摘要、方法与讨论相关段，未复算原始数据或宣称全文研究复现。","不作临床诊断，不用于识别或评分现实读者。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-11/lecture.md","sourcesPath":"/reading-assets/S-2-11/sources.json","sourceSlicePath":"/reading-assets/S-2-11/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-11/diagrams.md"},"2.12":{"title":"2.12　前瞻与推演的方法边界","lead":"推演可以很丰富，现实记录却不能跟着想象改变。要评价一次前瞻，必须知道当时到底掌握了什么、承诺预测什么，以及什么时候算对或算错。","explanation":["原文定位：第407—412行；原文锚点 section-2-12；短引文：‘假设和模拟不回写现实事实’。本题源切片逐字附后，讲解与原文分开。","推演输入可以有观察、报告、计划、假设和模拟事件，但要保留类型。观察也有测量限制；报告是有人如此说，内容还需核；计划是准备做，不能记成执行；假设和模拟只在相应条件下进入模型，不得回写已发生的事实。材料进入同一运行界面，不代表其真实性或证据等级相同。","每次运行冻结联合快照：对象及圈层状态、证据截止、机制、参数范围、时钟、传播规则和停止条件。尤其区分事件什么时候发生与研究者什么时候知道；事后才获知的材料，即使描述较早的事件，也不能悄悄塞回原来那次前瞻的可用输入。","条件前瞻在结果前登记目标、期限、对象和圈层范围、输入截止、简单基线、路径、表达方式、校准指标、早期信号、反向信号、暂停、退役与结果回写。预测一句“以后会改善”不够可评：改善哪个量、在什么时间内、对谁、相对于什么，都要清楚。","多条路径不是为事后任挑命中准备的保险箱。路径怎样表达和聚合须事先确定；不能结果后更换目标、延长期限、缩小群体或合并路径，再把新版答案算成旧版成功。新信息可以改进下一版，旧版仍按当时合同评价并保留偏差。","校准与某一次命中不同。一次高概率事件没有发生，不立即证明整体校准失败；一次命中也不证明模型有长期优势。要按预先选择的评分、基线和评价单位累计检验，注意事件之间的依赖；条件一变、评价单位一换，都可能改变所评价的目标。","本节不是禁止模拟或计划。模拟能探索假设后果，计划能提示可能未来事件，更新能反映新知识；关键是保存身份与版本。下面真实案例只说明论文中的反事实模拟数字不能被讲成实际实施成效，不声称该论文是一次通过本框架合同的未来预测。"],"distinctions":[{"leftTitle":"报告","leftText":"某来源声称发生，须核真实性。","rightTitle":"观察事实","rightText":"有相应观察依据，仍保留测量边界。"},{"leftTitle":"计划","leftText":"准备实施的安排。","rightTitle":"执行","rightText":"实际发生的行动与时间，需事件记录。"},{"leftTitle":"模拟结果","leftText":"在模型与参数下算出的后果。","rightTitle":"实际成效","rightText":"现实执行和结局的材料及因果依据。"},{"leftTitle":"新版前瞻","leftText":"新信息或新条件下另行运行。","rightTitle":"改写旧命中","rightText":"把事后改变当作先前成功，破坏评价。"}],"boundaries":["反事实重排患者构成的计算，不证明已经实际改造算法、增加真实照护或改善健康；来源身份必须保留。","一项概率预测的单次得失不等于整体校准结论；样本依赖、任务混合和选择性汇报也会影响评价。","冻结快照不保证机制正确，也不保证执行未偏离；它提供可复核的固定依据，后续仍须查运行和反例。"],"questions":["一个报告称某事件昨天发生，但今天才收到，昨天的预测能把它当已知输入吗？","论文模拟显示某比例将增加，能否写“实施后该比例已增加”？","原先截止9月30日，10月才达成目标，能改期限让原预测算对吗？"],"diagramPath":"/reading-assets/S-2-12/figures/section-2-12.png","caseLinks":[{"title":"2019年算法论文里的17.7%与46.5%：这是反事实重排","href":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf"}],"caseNotes":[{"title":"2019年算法论文里的17.7%与46.5%：这是反事实重排","text":"Obermeyer等在第97百分位阈值处，通过反事实重排估计自动识别者中的黑人比例会由17.7%变为46.5%。原文明确写为模拟情景；不是已经实施后的观察性改善。","sourceLabel":"Obermeyer et al. 2019，counterfactual simulation及Fig.1B","sourceUrl":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf","sourceLocator":"Science366:447—453；印刷p.449，Fig.1B前的反事实模拟段及图注；PDF第3页","boundary":"分母是指定阈值下自动识别者，不是所有患者。结果是模拟选入构成，不是实际新增照护、个体健康或长期效果；本讲未复算数据。","href":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf"}],"sourceRefs":[{"section":"2.12","start_line":407,"end_line":412,"startLine":407,"endLine":412}],"outputId":"section-2-12","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：预测评价需要一个结果前可定位的承诺和当时可用信息集；否则无法区分预测与事后解释。","冻结：明确输入截止、对象快照、机制及参数、事件时钟和停止规则，保留材料类型。","公开推演：由已声明输入和规则产生带条件的路径或概率，不把中间模拟节点标为现实观察。","评价：在原期限与原目标下对照现实结果及预设基线；新信息只进入新版本，不改写旧输入或成功条件。","结论：可以给出条件前瞻与模拟后果，但只能按其身份使用；实际行动还需独立证据、规范和授权。"],"teachingExamples":[{"title":"教学构造：晚到的信息只能生成新版","text":"假设V1在6月1日截止资料，预测同一项目9月30日前达到指定验收条件。10月5日才收到“8月已经停工”的报告：报告内容涉及较早事件，但它并非V1时已知输入。可核实后进入V2或解释V1偏差，不能声称V1早已使用它。若11月建成，也不能把V1期限改到年底以报命中。","assumptions":"项目、日期、停工和结果均是教学设定，不对应真实工程。","boundary":"只示范版本和两种时间的区别，不评估任何现实项目。"},{"title":"教学数学构造：评分规则先定，不凭喜欢挑","text":"假设事前约定对二元结果y用平方误差(p−y)²计分，越小越好。一次预测p=0.8而结果y=0，分数为0.64；基线p=0.5的同次分数为0.25。此例只说明在该次预设规则下前者较差，不足以证明前者在所有任务中更差或总体失准。","assumptions":"概率、结果与评分全为教学给定，未实施任何真实前瞻。","boundary":"不能将单次评分当整体校准，亦不能结果后换一个有利评分。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Obermeyer等2019年论文中，17.7%到46.5%的变化是在97百分位阈值下反事实重排所估的自动识别者黑人占比。","effect":"这是模拟构成变化，不能写成真实实施后已观察到的照护改善。","sourceIds":["obermeyer-simulation"]},{"identity":"constructed_boundary","text":"教学边界：原先预测某全体人群在年底改善，结果后只选改善的子群并延长半年，仍算原预测命中。","effect":"目标人群和期限已改，必须建立新记录，原预测按原合同评价。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一个报告称某事件昨天发生，但今天才收到，昨天的预测能把它当已知输入吗？","answer":"不能。事件时间与信息到达时间不同；核实后进入新版本，旧版保留原信息截止。","basis":"本节原文及上述公开推导"},{"question":"论文模拟显示某比例将增加，能否写“实施后该比例已增加”？","answer":"不能。模拟不是执行和观察；需要实际实施及结果材料。","basis":"本节原文及上述公开推导"},{"question":"原先截止9月30日，10月才达成目标，能改期限让原预测算对吗？","answer":"不能。新期限构成新记录，原版本按原期限结案；可以解释原因但不改写命中。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-12/figures/section-2-12.png","alt":"V1输入截止，类型／联合快照／时钟；V1条件推演，机制／参数／路径；按原合同评价V1，目标／期限／基线；截止后新材料，不倒填旧输入；V2新版本，新依据与新条件；保留两版记录，模拟仍非观察事实。版本与材料身份图，依据2.12；不表示模拟已实现，也不展示虚构预测效果。","caption":"版本与材料身份图，依据2.12；不表示模拟已实现，也不展示虚构预测效果。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。可切换V1/V2查看当时输入与不同结果，旧版本保持不可改写；观察、报告、计划、假设、模拟应有持续可见的类型标签。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实论文明确区分原始分组与模拟重排，适合检验“模拟不回写现实”；不把它冒作本讲完成的前瞻实验。"},"openQuestions":["若要主张真实部署改变了照护及健康，需要后续实施、时间窗和结局资料，以及相应效果比较；本讲不具备这些材料。"],"taskId":"S-2-12","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第407—412行；每节精确范围见sourceRefs","claim_support":["2.12：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"obermeyer-simulation","title":"Obermeyer et al. 2019，反事实模拟段","url":"https://www.ftc.gov/system/files/documents/public_events/1548288/privacycon-2020-ziad_obermeyer.pdf","source_type":"primary","version_or_date":"2019-10-25，Science366:447—453","locator":"印刷p.449，Fig.1B前段及图注；PDF第3页","claim_support":["2.12：在97百分位阈值的反事实重排下，自动识别者黑人占比17.7%到46.5%；原文明示simulated。"],"limits":["文本数值、分母与模拟身份已核；未获取个体资料复算。","不把模拟选入构成变化当作真实实施成效、健康收益或通过本框架的前瞻实例。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-12/lecture.md","sourcesPath":"/reading-assets/S-2-12/sources.json","sourceSlicePath":"/reading-assets/S-2-12/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-12/diagrams.md"},"2.13":{"title":"2.13　自主完善变量的上限","lead":"模型发现解释不了的地方，可以帮忙提出下一步问题；它不能替世界填写答案。补全的上限是候选、可观察含义和风险可接受的最小检验。","explanation":["原文定位：第413—420行；原文锚点 section-2-13；短引文：‘保持未知比主动补全更合适’。本题源切片逐字附后，讲解与原文分开。","原文只允许三种自主动作。第一，从残差提出多个竞争候选，而不是挑一个听起来最像答案的隐藏变量；第二，说明每个候选可能经哪条通道产生哪些可观察含义；第三，设计风险可接受的最小检验。设计检验不等于已获授权执行，也不等于已获得检验结果。","残差是现有表示或模型尚未解释的部分。它可能来自真实过程变化、测量和报告改变、样本选择、模型形式不合适或其他未建模条件；“有残差”并不独自证明一种新人格、圈层或因果机制存在。候选应能在目标和材料上相互区分，不能只是给同一未知换几个漂亮名字。","把候选改写为可观察含义：如果测量口径变了，应在哪些字段、协议或可比记录上看到差异；如果资源受限，应出现什么时点和约束对应；如果只是样本构成变化，按构成对齐后预期怎样改变。每个推论都要公开条件与反向信号；无法区分时就保留未决。","候选状态依次经历提出、检验中、得到支持的候选、拒绝或退役；这些不是强制单向升级的成熟度榜。得到支持的候选仍有对象、窗口与设计边界；要主张正式G支持、稳定人格、有效圈层或实际机制，还要满足各自合同，不能从“模型建议”直接跳到“观察事实”。","涉及隐私、健康、安全、法律地位或低权力位置时，先审查获取必要性、用途和伤害。一个问题可能理论上能减少不确定性，却与当前任务无关或暴露过大；信息价值不足以覆盖风险时，保持未知更合适。保护和权利也不应被粗暴折成一个任意数值，声称收益更大便无限索取。","最小检验指足以区分当前关键候选、且风险与权限可接受的方案，不是无限收集所有可取得数据。可以先查非敏感的测量协议与公开记录，或改进模型表示；若所需检验越权、超专业能力或不可安全实施，就停止该路线，保留缺口。"],"distinctions":[{"leftTitle":"变量候选","leftText":"对未知的一种可检验提案。","rightTitle":"现实取值","rightText":"由适当材料获得，不能靠提案生成。"},{"leftTitle":"设计最小检验","leftText":"说明怎样区分候选及其风险。","rightTitle":"执行并得到结果","rightText":"需要真实授权、参与和记录，另有证据身份。"},{"leftTitle":"候选得到支持","leftText":"在相应设计和窗口内获得有限依据。","rightTitle":"所有相关强主张成立","rightText":"人格、圈层、G资格与机制还须各自合同。"},{"leftTitle":"信息有用","leftText":"可能减少某种不确定性。","rightTitle":"有必要且可正当取得","rightText":"须审用途、风险、权限与替代方法。"}],"boundaries":["不能从预测失败自动推断对方隐瞒、人格异常或有隐藏组织；竞争候选与测量问题必须保留。","“最小”不等于规模小就无风险；一个敏感问题或单次不可逆行动也可能越界。","单纯证据不足时保持未决；有相应反证或预定排除理由时可拒绝，不再适用或不值得继续时可有理由退役。保留失败记录；退役不证明它在一切可能对象上永远不存在。","本讲未进行真实读者测量或干预，真实研究案例只说明其作者如何设计区分性检验，不将该设计转成对读者的指令。"],"questions":["发现残差后，最有说服力的一个故事能直接填为原因吗？","一个敏感字段可能提高预测精度，是否足以授权收集？","候选在某窗口获得支持后，能否立即写成稳定人格或正式G机制？"],"diagramPath":"/reading-assets/S-2-13/figures/section-2-13.png","caseLinks":[{"title":"Fleeson的测量替代解释：先让候选能够被区分","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"caseNotes":[{"title":"Fleeson的测量替代解释：先让候选能够被区分","text":"Fleeson 2001年研究2针对形容词理解差异要求参与者学习统一定义，研究3用双极量尺检验单极量尺使用可能造成的变异解释。本节借此说明：研究者把替代解释转成了可比较的测量条件，而不是直接用标签补全真实属性。","sourceLabel":"Fleeson 2001，Study2与Study3方法","sourceUrl":"https://simine.com/407/readings/Fleeson_2001.pdf","sourceLocator":"印刷pp.1019—1020 Study2引言与方法；pp.1021—1022 Study3引言与方法","boundary":"这是作者已报告的研究设计；不等于本讲执行了测量，不证明所有量表偏差或人格机制已被排除，也不追授本框架正式G资格。","href":"https://simine.com/407/readings/Fleeson_2001.pdf"}],"sourceRefs":[{"section":"2.13","start_line":413,"end_line":420,"startLine":413,"endLine":420}],"outputId":"section-2-13","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["前提：现模型的失败显示“已有解释不足”，没有唯一决定新的原因。","候选生成：列出多个彼此有差异的解释，并明确它们改变哪个量、经哪条通道、在何种窗口产生什么可观察结果。","风险门：先检查信息是否必要、允许用于什么、谁可能受伤害、是否有低风险替代与停止路径。","检验连接：只在具备授权和风险条件时实施相称最小检验；当前讲解只设计方案，不实际招募、测量或收集个人资料。","结论：按真实所得材料更新候选的支持、拒绝或退役；没有足够证据时保持未知，不以自动补值创造事实。"],"teachingExamples":[{"title":"教学构造：等待时间的残差，不用猜人的健康","text":"假设模型低估了某服务的等待时长。可提出三个候选：到达率改变、处理资源减少、计时口径由排队时刻改为提交时刻。分别查公开到达计数、值班容量和计时协议，预先说明何种对齐会削弱每个候选。若这些非敏感记录尚未查清，直接搜集工作人员健康或家庭信息既不是必要第一步，也不能因“有信息价值”而自动授权。","assumptions":"服务与残差完全为教学设定；未取得实际个人或运营数据。","boundary":"方案展示竞争解释和低风险优先，不执行调查，不断言任何候选真实。"},{"title":"教学条件反例：多个解释暂时无法区分","text":"假设现有记录只有每天的总等待量，到达增加与处理下降都能给出同一总量。只增加更多同型总量未必能区分；可考虑在已有权限内补充到达与完成的分项记录。若分项不能取得且敏感替代不可接受，结果就是两候选未决，而不是任选一个填入事实表。","assumptions":"可识别性情境为自拟；权限与风险必须在实际场景另行核查。","boundary":"不证明所有额外数据都无用，不生成现实机制。"}],"counterexamples":[{"identity":"real_counterevidence","text":"Fleeson研究把量表用词理解差异和单极量尺使用当作待检测量解释，分别设计统一定义和双极量尺条件。","effect":"解释竞争通过改变可区分的测量条件来检验，而不是把表面分数差自动指定为真实人格差异；本讲不宣称所有测量偏差都被排除。","sourceIds":["fleeson-test"]},{"identity":"constructed_boundary","text":"教学边界：模型提出“可能抑郁”作为未解释行为的隐藏变量，随即自动填成该人的真实健康状态。","effect":"从候选越级为敏感事实且超出本框架诊断边界，应保留未知并停止不当补全。","sourceIds":["theory"]}],"questionAnswers":[{"question":"发现残差后，最有说服力的一个故事能直接填为原因吗？","answer":"不能。要列竞争候选、可观察含义和能区分它们的检验；故事连贯不替代材料。","basis":"本节原文及上述公开推导"},{"question":"一个敏感字段可能提高预测精度，是否足以授权收集？","answer":"不足。先核必要性、用途、风险、低权力影响和可替代方法；保持未知可能更合适。","basis":"本节原文及上述公开推导"},{"question":"候选在某窗口获得支持后，能否立即写成稳定人格或正式G机制？","answer":"不能。支持范围仍由设计和材料限定，其他类型的强主张须另满足对应合同。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-2-13/figures/section-2-13.png","alt":"已有模型的残差，表示或解释不足；多个竞争候选，不自动选定原因；可观察含义，通道／窗口／反向信号；必要性与风险审查，隐私／权限／低风险替代；最小检验方案，执行须另有真实授权；依材料更新状态，支持／未决／拒绝／退役。方法示意图，依据2.13；候选不自动成为事实，图示不代表本讲实施了任何试验。","caption":"方法示意图，依据2.13；候选不自动成为事实，图示不代表本讲实施了任何试验。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。可切换某检验的风险或权限状态，显示路线暂停并保持未知；不能将生成候选的按钮设计成自动填充敏感事实。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原研究的测量竞争解释与设计直接展示“候选→可观察差异→检验”，不需要对读者进行任何真实试验。"},"openQuestions":["实际新增变量是否值得获取，必须结合具体任务、现有资料、权限和潜在伤害；本讲不替任何真实个人填写敏感取值。"],"taskId":"S-2-13","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第413—420行；每节精确范围见sourceRefs","claim_support":["2.13：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"fleeson-test","title":"Fleeson 2001，Study2及Study3的测量解释检验","url":"https://simine.com/407/readings/Fleeson_2001.pdf","source_type":"primary","version_or_date":"2001-06，DOI10.1037/0022-3514.80.6.1011","locator":"JPSP80(6):1011—1027；pp.1019—1020统一定义；pp.1021—1022双极量尺","claim_support":["2.13：研究2用统一形容词定义应对解释差异；研究3用双极量尺检查单极尺度使用的替代解释。"],"limits":["同一研究项目中的不同设计，不按文件数或举例次数增加独立支持。","只使用已读方法段；不声称所有测量偏差已排除、不对读者进行人格测试。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-2-13/lecture.md","sourcesPath":"/reading-assets/S-2-13/sources.json","sourceSlicePath":"/reading-assets/S-2-13/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-2-13/diagrams.md"}}},"headers":[],"relativePath":"theory/part-02.md","filePath":"theory/part-02.md"}'),c={name:"theory/part-02.md"};function u(d,e,p,g,h,m){const t=r("SectionLesson");return n(),o("div",null,[e[0]||(e[0]=s("",1)),a(t,{section:"intro-02-part"}),e[1]||(e[1]=s("",1)),a(t,{section:"2.1"}),e[2]||(e[2]=s("",1)),a(t,{section:"2.1.1"}),e[3]||(e[3]=s("",1)),a(t,{section:"2.1.2"}),e[4]||(e[4]=s("",1)),a(t,{section:"2.2"}),e[5]||(e[5]=s("",1)),a(t,{section:"2.3"}),e[6]||(e[6]=s("",1)),a(t,{section:"2.3.1"}),e[7]||(e[7]=s("",1)),a(t,{section:"2.4"}),e[8]||(e[8]=s("",1)),a(t,{section:"2.4.1"}),e[9]||(e[9]=s("",1)),a(t,{section:"2.4.2"}),e[10]||(e[10]=s("",1)),a(t,{section:"2.5"}),e[11]||(e[11]=s("",1)),a(t,{section:"2.5.1"}),e[12]||(e[12]=s("",1)),a(t,{section:"2.6"}),e[13]||(e[13]=s("",1)),a(t,{section:"2.6.1"}),e[14]||(e[14]=s("",1)),a(t,{section:"2.7"}),e[15]||(e[15]=s("",1)),a(t,{section:"2.7.1"}),e[16]||(e[16]=s("",1)),a(t,{section:"2.7.2"}),e[17]||(e[17]=s("",1)),a(t,{section:"2.8"}),e[18]||(e[18]=s("",1)),a(t,{section:"2.9"}),e[19]||(e[19]=s("",1)),a(t,{section:"2.10"}),e[20]||(e[20]=s("",1)),a(t,{section:"2.11"}),e[21]||(e[21]=s("",1)),a(t,{section:"2.12"}),e[22]||(e[22]=s("",1)),a(t,{section:"2.13"}),e[23]||(e[23]=l("div",{class:"theory-source"},null,-1))])}const f=i(c,[["render",u]]);export{b as __pageData,f as default};
